import{f as a,o,c as t,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"Registro de decisiones de arquitectura (ADR) — GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/27-registro-adr.md","filePath":"entregables-analisis-diseno/27-registro-adr.md","lastUpdated":null}'),n={name:"entregables-analisis-diseno/27-registro-adr.md"};function r(i,e,s,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="registro-de-decisiones-de-arquitectura-adr-—-goodapps-cooperativas" tabindex="-1">Registro de decisiones de arquitectura (ADR) — GoodApps Cooperativas <a class="header-anchor" href="#registro-de-decisiones-de-arquitectura-adr-—-goodapps-cooperativas" aria-label="Permalink to &quot;Registro de decisiones de arquitectura (ADR) — GoodApps Cooperativas&quot;">​</a></h1><p><strong>Entregable de Análisis y Diseño Detallado — Artefacto 5.3 (Registro de decisiones de arquitectura)</strong></p><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Producto</td><td>GoodApps Cooperativas — plataforma SaaS multitenant de gestión para cooperativas de servicios, reemplazo de ProCoop</td></tr><tr><td>Documento</td><td>Registro de decisiones de arquitectura y técnicas, en formato ADR (Michael Nygard / MADR)</td></tr><tr><td>Artefacto</td><td>5.3 Registro de decisiones de arquitectura (ADR) del índice <code>00-INDICE.md</code></td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr><tr><td>Estado</td><td>Borrador para revisión</td></tr><tr><td>Fuentes</td><td><code>docs/especificacion/01-registro-decisiones.md</code> (DEC-001 a DEC-089); <code>00-ESPECIFICACION-MAESTRA.md</code> §3, §5, §6, §13 y §14; anexos T01 (plataforma), T02 (identidad, roles y auditoría), T05 (modelo de datos), T06 (integraciones y bóveda <code>integrationSecrets</code>), T07 (migración), T08 (no funcionales y seguridad), T10 y T11 en lo citado; <code>02-preguntas-abiertas.md</code>; documento de arquitectura <code>02-arquitectura-c4.md</code> de esta carpeta</td></tr><tr><td>Carácter</td><td>Documento derivado. No reemplaza la especificación: ante cualquier diferencia prevalecen la maestra, los anexos y el registro de decisiones <code>01</code>.</td></tr></tbody></table><h2 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Autor</th><th>Cambios</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Equipo de análisis y diseño (a definir nominalmente)</td><td>Versión inicial: 55 ADR derivados de las decisiones técnicas del registro <code>01</code> y de las decisiones implícitas en T01, T02, T05, T06, T07 y T08; lista de DEC no técnicas excluidas; observaciones e inconsistencias.</td></tr></tbody></table><h2 id="aprobaciones" tabindex="-1">Aprobaciones <a class="header-anchor" href="#aprobaciones" aria-label="Permalink to &quot;Aprobaciones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rol</th><th>Nombre</th><th>Fecha</th><th>Firma</th></tr></thead><tbody><tr><td>Responsable de arquitectura</td><td>A definir</td><td>—</td><td>—</td></tr><tr><td>Responsable de seguridad (P-SEC)</td><td>A definir</td><td>—</td><td>—</td></tr><tr><td>Responsable de operaciones (P-OPS)</td><td>A definir</td><td>—</td><td>—</td></tr><tr><td>Representante del solicitante</td><td>A definir</td><td>—</td><td>—</td></tr></tbody></table><hr><h2 id="indice-de-adr" tabindex="-1">Índice de ADR <a class="header-anchor" href="#indice-de-adr" aria-label="Permalink to &quot;Índice de ADR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Título</th><th>Estado</th><th>Origen principal</th></tr></thead><tbody><tr><td><a href="#adr-001--stack-tecnológico-nodejs-mongodb-y-vue">ADR-001</a></td><td>Stack tecnológico Node.js, MongoDB y Vue</td><td>Aceptada</td><td>DEC-001</td></tr><tr><td><a href="#adr-002--monolito-modular-con-fronteras-estrictas">ADR-002</a></td><td>Monolito modular con fronteras estrictas</td><td>Aceptada</td><td>DEC-003</td></tr><tr><td><a href="#adr-003--despliegue-en-contenedores-agnóstico-de-nube">ADR-003</a></td><td>Despliegue en contenedores agnóstico de nube</td><td>Aceptada</td><td>DEC-004</td></tr><tr><td><a href="#adr-004--región-de-alojamiento-aws-sa-east-1">ADR-004</a></td><td>Región de alojamiento AWS sa-east-1</td><td>Aceptada</td><td>DEC-062</td></tr><tr><td><a href="#adr-005--continuidad-replica-set-multizona-pitr-y-restauración-por-tenant">ADR-005</a></td><td>Continuidad: replica set multizona, PITR y restauración por tenant</td><td>Aceptada</td><td>DEC-063</td></tr><tr><td><a href="#adr-006--design-system-propio-sin-librerías-de-interfaz-de-terceros">ADR-006</a></td><td>Design system propio sin librerías de interfaz de terceros</td><td>Aceptada</td><td>T01 §7.1</td></tr><tr><td><a href="#adr-007--configuración-tipada-y-versionada-y-diccionario-de-textos">ADR-007</a></td><td>Configuración tipada y versionada y diccionario de textos</td><td>Aceptada</td><td>ARQ-05, ARQ-07</td></tr><tr><td><a href="#adr-008--extensibilidad-acotada-sin-ejecución-dinámica-de-código">ADR-008</a></td><td>Extensibilidad acotada, sin ejecución dinámica de código</td><td>Aceptada</td><td>DEC-079; RF-PLA-155</td></tr><tr><td><a href="#adr-009--base-de-datos-única-compartida-con-tenantid">ADR-009</a></td><td>Base de datos única compartida con <code>tenantId</code></td><td>Aceptada</td><td>DEC-002</td></tr><tr><td><a href="#adr-010--aislamiento-de-tenant-forzado-en-todas-las-superficies">ADR-010</a></td><td>Aislamiento de tenant forzado en todas las superficies</td><td>Aceptada</td><td>DEC-002; RF-PLA-019 a RF-PLA-034</td></tr><tr><td><a href="#adr-011--tenant-platform-y-colecciones-globales-en-lista-blanca">ADR-011</a></td><td>Tenant <code>PLATFORM</code> y colecciones globales en lista blanca</td><td>Aceptada</td><td>RF-PLA-023, RF-PLA-036; DEC-065</td></tr><tr><td><a href="#adr-012--colas-por-clase-de-carga-y-cuotas-por-tenant">ADR-012</a></td><td>Colas por clase de carga y cuotas por tenant</td><td>Aceptada</td><td>DEC-075; RN-NFR-025</td></tr><tr><td><a href="#adr-013--copia-entre-tenants-y-plantillas-de-plataforma-sin-datos-personales">ADR-013</a></td><td>Copia entre tenants y plantillas de plataforma sin datos personales</td><td>Aceptada</td><td>DEC-025, DEC-026</td></tr><tr><td><a href="#adr-014--outbox-transaccional-inbox-idempotente-y-workers-bullmq">ADR-014</a></td><td>Outbox transaccional, inbox idempotente y workers BullMQ</td><td>Aceptada</td><td>DEC-003; RF-PLA-008 a RF-PLA-011</td></tr><tr><td><a href="#adr-015--redis-no-es-fuente-de-verdad">ADR-015</a></td><td>Redis no es fuente de verdad</td><td>Aceptada</td><td>RNF-NFR-041</td></tr><tr><td><a href="#adr-016--almacén-analítico-en-un-miembro-dedicado-del-replica-set">ADR-016</a></td><td>Almacén analítico en un miembro dedicado del replica set</td><td>Aceptada (asumida, DEC-072)</td><td>PA-BIA-01; RF-PLA-035</td></tr><tr><td><a href="#adr-017--dinero-en-decimal128-y-decimaljs">ADR-017</a></td><td>Dinero en <code>Decimal128</code> y <code>decimal.js</code></td><td>Aceptada</td><td>RN-NFR-005; RN-DAT-005</td></tr><tr><td><a href="#adr-018--idempotencia-por-idempotency-key-y-claves-naturales">ADR-018</a></td><td>Idempotencia por <code>Idempotency-Key</code> y claves naturales</td><td>Aceptada</td><td>RN-NFR-007; ARQ-02</td></tr><tr><td><a href="#adr-019--transacciones-multidocumento-y-control-optimista">ADR-019</a></td><td>Transacciones multidocumento y control optimista</td><td>Aceptada</td><td>RNF-NFR-210, RNF-NFR-211</td></tr><tr><td><a href="#adr-020--documentos-económicos-inmutables-y-anulación-por-contrapartida">ADR-020</a></td><td>Documentos económicos inmutables y anulación por contrapartida</td><td>Aceptada</td><td>RN-DAT-004; RN-NFR-017</td></tr><tr><td><a href="#adr-021--instantes-en-utc-y-fechas-de-negocio-en-la-zona-del-tenant">ADR-021</a></td><td>Instantes en UTC y fechas de negocio en la zona del tenant</td><td>Aceptada</td><td>RN-NFR-018; RN-DAT-006</td></tr><tr><td><a href="#adr-022--personas-jurídicas-por-tenant-y-cuenta-corriente-por-entidad">ADR-022</a></td><td>Personas jurídicas por tenant y cuenta corriente por entidad</td><td>Aceptada</td><td>DEC-064, DEC-087</td></tr><tr><td><a href="#adr-023--contrato-de-api-zod-rfc-9457-y-paginación-uniforme">ADR-023</a></td><td>Contrato de API: Zod, RFC 9457 y paginación uniforme</td><td>Aceptada</td><td>RF-PLA-014, RF-PLA-015</td></tr><tr><td><a href="#adr-024--versionado-de-api-externa-y-de-eventos">ADR-024</a></td><td>Versionado de API externa y de eventos</td><td>Aceptada</td><td>RNF-NFR-174 a RNF-NFR-179</td></tr><tr><td><a href="#adr-025--identidad-común-con-pertenencias-privadas-por-tenant">ADR-025</a></td><td>Identidad común con pertenencias privadas por tenant</td><td>Aceptada</td><td>RF-IAM-001 a RF-IAM-010</td></tr><tr><td><a href="#adr-026--autenticación-del-personal-y-modelo-de-sesión">ADR-026</a></td><td>Autenticación del personal y modelo de sesión</td><td>Aceptada</td><td>RF-IAM-021, RF-IAM-035; RNF-NFR-060 a RNF-NFR-064</td></tr><tr><td><a href="#adr-027--ingreso-del-socio-con-contraseña-u-otp-sin-enlace-mágico">ADR-027</a></td><td>Ingreso del socio con contraseña u OTP, sin enlace mágico</td><td>Aceptada</td><td>DEC-066</td></tr><tr><td><a href="#adr-028--proveedores-de-identidad-federados-y-cidi-córdoba">ADR-028</a></td><td>Proveedores de identidad federados y CiDi Córdoba</td><td>Aceptada</td><td>DEC-067</td></tr><tr><td><a href="#adr-029--autorización-por-capabilities-en-capas-con-denegación-por-defecto">ADR-029</a></td><td>Autorización por capabilities en capas con denegación por defecto</td><td>Aceptada</td><td>RF-IAM-060, RF-IAM-061; RNF-NFR-090</td></tr><tr><td><a href="#adr-030--acceso-de-soporte-temporal-y-acceso-de-emergencia">ADR-030</a></td><td>Acceso de soporte temporal y acceso de emergencia</td><td>Aceptada con validación pendiente</td><td>RF-PLA-101 a RF-PLA-106; PA-PLA-05</td></tr><tr><td><a href="#adr-031--auditoría-transaccional-inmutable-con-cadena-de-hash">ADR-031</a></td><td>Auditoría transaccional inmutable con cadena de hash</td><td>Aceptada</td><td>RNF-NFR-110 a RNF-NFR-119</td></tr><tr><td><a href="#adr-032--bóveda-de-secretos-propia-con-cifrado-por-sobre-y-kms">ADR-032</a></td><td>Bóveda de secretos propia con cifrado por sobre y KMS</td><td>Aceptada</td><td>DEC-074</td></tr><tr><td><a href="#adr-033--cifrado-de-campos-sensibles-por-tenant-y-categoría">ADR-033</a></td><td>Cifrado de campos sensibles por tenant y categoría</td><td>Aceptada</td><td>RNF-NFR-055 a RNF-NFR-057</td></tr><tr><td><a href="#adr-034--secretos-de-plataforma-en-gestor-de-secretos-y-arranque-seguro">ADR-034</a></td><td>Secretos de plataforma en gestor de secretos y arranque seguro</td><td>Aceptada</td><td>RNF-PLA-001; RNF-NFR-067, RNF-NFR-070</td></tr><tr><td><a href="#adr-035--almacenamiento-de-objetos-privado-con-url-firmadas-y-antivirus">ADR-035</a></td><td>Almacenamiento de objetos privado con URL firmadas y antivirus</td><td>Aceptada</td><td>RF-PLA-012; RNF-NFR-058, RNF-NFR-078 a RNF-NFR-081</td></tr><tr><td><a href="#adr-036--integraciones-solo-por-conectores-con-estados-explícitos">ADR-036</a></td><td>Integraciones solo por conectores con estados explícitos</td><td>Aceptada</td><td>ARQ-06; DEC-041</td></tr><tr><td><a href="#adr-037--webhooks-entrantes-como-disparadores-verificados">ADR-037</a></td><td>Webhooks entrantes como disparadores verificados</td><td>Aceptada</td><td>RF-INT-053 a RF-INT-057; RN-NFR-008</td></tr><tr><td><a href="#adr-038--egreso-controlado-y-protección-contra-ssrf">ADR-038</a></td><td>Egreso controlado y protección contra SSRF</td><td>Aceptada</td><td>RF-INT-079; RNF-NFR-087</td></tr><tr><td><a href="#adr-039--emisión-fiscal-con-contingencia-y-numeración-sin-huecos">ADR-039</a></td><td>Emisión fiscal con contingencia y numeración sin huecos</td><td>Aceptada</td><td>DEC-018, DEC-035, DEC-038</td></tr><tr><td><a href="#adr-040--certificado-arca-generado-en-la-plataforma">ADR-040</a></td><td>Certificado ARCA generado en la plataforma</td><td>Aceptada</td><td>DEC-053</td></tr><tr><td><a href="#adr-041--credenciales-de-proveedor-de-plataforma-o-propias-del-tenant">ADR-041</a></td><td>Credenciales de proveedor de plataforma o propias del tenant</td><td>Aceptada</td><td>DEC-020, DEC-077</td></tr><tr><td><a href="#adr-042--proveedores-iniciales-detrás-de-adaptadores-canónicos">ADR-042</a></td><td>Proveedores iniciales detrás de adaptadores canónicos</td><td>Aceptada</td><td>DEC-015, DEC-046, DEC-055</td></tr><tr><td><a href="#adr-043--aprovisionamiento-automático-asíncrono-con-respaldo-manual">ADR-043</a></td><td>Aprovisionamiento automático asíncrono con respaldo manual</td><td>Aceptada</td><td>DEC-041, DEC-042</td></tr><tr><td><a href="#adr-044--la-inteligencia-artificial-solo-propone">ADR-044</a></td><td>La inteligencia artificial solo propone</td><td>Aceptada</td><td>ARQ-08; DEC-056</td></tr><tr><td><a href="#adr-045--motor-de-pdf-con-chromium-sin-interfaz-en-workers-dedicados">ADR-045</a></td><td>Motor de PDF con Chromium sin interfaz en workers dedicados</td><td>Aceptada</td><td>DEC-080</td></tr><tr><td><a href="#adr-046--interfaz-de-firma-propia-con-otp-y-firma-digital-licenciada">ADR-046</a></td><td>Interfaz de firma propia con OTP y firma digital licenciada</td><td>Aceptada</td><td>DEC-078</td></tr><tr><td><a href="#adr-047--pwa-única-con-cola-offline-idempotente">ADR-047</a></td><td>PWA única con cola offline idempotente</td><td>Aceptada</td><td>RNF-NFR-187; RNF-NFR-219</td></tr><tr><td><a href="#adr-048--agente-local-propio-con-canal-saliente">ADR-048</a></td><td>Agente local propio con canal saliente</td><td>Aceptada (asumida, DEC-072)</td><td>PA-INT-09; RF-INT-084</td></tr><tr><td><a href="#adr-049--encargado-de-tratamiento-exportación-purga-y-libro-de-supresiones">ADR-049</a></td><td>Encargado de tratamiento: exportación, purga y libro de supresiones</td><td>Aceptada</td><td>DEC-076</td></tr><tr><td><a href="#adr-050--observabilidad-con-opentelemetry-y-correlación-extremo-a-extremo">ADR-050</a></td><td>Observabilidad con OpenTelemetry y correlación extremo a extremo</td><td>Aceptada</td><td>RNF-NFR-119 a RNF-NFR-139</td></tr><tr><td><a href="#adr-051--entrega-continua-con-imágenes-firmadas-y-migraciones-expandircontraer">ADR-051</a></td><td>Entrega continua con imágenes firmadas y migraciones expandir/contraer</td><td>Aceptada</td><td>RNF-NFR-164 a RNF-NFR-168</td></tr><tr><td><a href="#adr-052--ambientes-separados-y-datos-ficticios-fuera-de-producción">ADR-052</a></td><td>Ambientes separados y datos ficticios fuera de producción</td><td>Aceptada</td><td>RF-PLA-109, RF-PLA-110; RN-NFR-014</td></tr><tr><td><a href="#adr-053--migración-con-extracción-de-solo-lectura-snapshots-e-histórico-acotado">ADR-053</a></td><td>Migración con extracción de solo lectura, snapshots e histórico acotado</td><td>Aceptada</td><td>DEC-070, DEC-087; RF-MIG-010, RF-MIG-011</td></tr><tr><td><a href="#adr-054--convivencia-con-procoop-y-corte-por-etapas">ADR-054</a></td><td>Convivencia con ProCoop y corte por etapas</td><td>Aceptada</td><td>DEC-068, DEC-069, DEC-088, DEC-089</td></tr><tr><td><a href="#adr-055--identificador-de-pago-autocontenido-durante-la-transición">ADR-055</a></td><td>Identificador de pago autocontenido durante la transición</td><td>Aceptada</td><td>DEC-050</td></tr></tbody></table><hr><h2 id="_1-proposito-alcance-y-convenciones" tabindex="-1">1. Propósito, alcance y convenciones <a class="header-anchor" href="#_1-proposito-alcance-y-convenciones" aria-label="Permalink to &quot;1. Propósito, alcance y convenciones&quot;">​</a></h2><h3 id="_1-1-proposito" tabindex="-1">1.1 Propósito <a class="header-anchor" href="#_1-1-proposito" aria-label="Permalink to &quot;1.1 Propósito&quot;">​</a></h3><p>Este registro documenta, en formato ADR, cada decisión de arquitectura o técnica vigente de GoodApps Cooperativas: el problema que resuelve, la opción elegida, las alternativas evaluadas y sus consecuencias. Sirve como fuente única para el equipo de desarrollo (asistido por Cursor IA, maestra §16) y como base de los ADR por archivo que exige RNF-NFR-243 en el repositorio de código (<code>docs/adr/NNNN-titulo.md</code>).</p><h3 id="_1-2-criterio-de-seleccion" tabindex="-1">1.2 Criterio de selección <a class="header-anchor" href="#_1-2-criterio-de-seleccion" aria-label="Permalink to &quot;1.2 Criterio de selección&quot;">​</a></h3><ul><li><strong>Incluidas</strong>: las DEC de <code>01-registro-decisiones.md</code> con efecto técnico (stack, datos, despliegue, seguridad, integraciones, documentos, identidad, migración) y las decisiones técnicas implícitas en los anexos T01, T02, T05, T06, T07 y T08 que cumplen al menos una condición de RNF-NFR-243: afectan a más de un módulo, a la seguridad o resuelven una contraposición técnica (CTR).</li><li><strong>Excluidas</strong>: las DEC de reglas de negocio puras (catálogo, facturación, mora, CRM, contabilidad funcional) y de organización del entregable. Se listan en la sección 3 con el motivo.</li><li>Una DEC puede originar varios ADR y un ADR puede consolidar varias DEC cuando resuelven el mismo problema técnico.</li></ul><h3 id="_1-3-convenciones" tabindex="-1">1.3 Convenciones <a class="header-anchor" href="#_1-3-convenciones" aria-label="Permalink to &quot;1.3 Convenciones&quot;">​</a></h3><ul><li><strong>Estados</strong>: <em>Aceptada</em> (DEC vigente o requisito <code>Adoptado</code>); <em>Aceptada (asumida, DEC-072)</em> cuando proviene de una pregunta abierta resuelta con la opción recomendada por la política DEC-047/DEC-072, revisable por el solicitante; <em>Aceptada con validación pendiente</em> cuando parte del requisito figura <code>A validar</code> en su anexo. Ningún ADR de este registro está <em>Reemplazado</em>; DEC-081 (reemplazada por DEC-088) no es técnica.</li><li><strong>Alternativas</strong>: se citan las opciones de la pregunta abierta (PA) o de la contraposición (CTR) que la especificación registra. Cuando la fuente no documenta alternativas, se indica <em>(alternativa de análisis, no registrada en la especificación)</em>.</li><li><strong>Origen</strong>: identificadores DEC, RF, RN, RNF, CTR, PA y ARQ de la especificación; las referencias a <code>02-arquitectura-c4.md</code> usan sus propios códigos (RT-, RA-, DT-).</li><li>Este registro no contradice <code>02-arquitectura-c4.md</code> §10, que es un resumen tabular; aquí se agregan alternativas, consecuencias y decisiones implícitas.</li></ul><hr><h2 id="_2-registro-de-decisiones" tabindex="-1">2. Registro de decisiones <a class="header-anchor" href="#_2-registro-de-decisiones" aria-label="Permalink to &quot;2. Registro de decisiones&quot;">​</a></h2><h3 id="_2-1-estilo-de-arquitectura-y-plataforma" tabindex="-1">2.1 Estilo de arquitectura y plataforma <a class="header-anchor" href="#_2-1-estilo-de-arquitectura-y-plataforma" aria-label="Permalink to &quot;2.1 Estilo de arquitectura y plataforma&quot;">​</a></h3><h4 id="adr-001-—-stack-tecnologico-node-js-mongodb-y-vue" tabindex="-1">ADR-001 — Stack tecnológico Node.js, MongoDB y Vue <a class="header-anchor" href="#adr-001-—-stack-tecnologico-node-js-mongodb-y-vue" aria-label="Permalink to &quot;ADR-001 — Stack tecnológico Node.js, MongoDB y Vue&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-001, vigente desde 04-11-2026)</td></tr><tr><td>Origen</td><td>DEC-001; maestra §3 y §5.1; RF-PLA-002; RT-01 de <code>02-arquitectura-c4.md</code>; CTR-NFR-05, CTR-NFR-11</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop es una aplicación .NET de escritorio sobre SQL Server con un portal (CoopOnline) sobre MySQL. El documento funcional previo (DFA) proponía .NET, Azure y SQL Server. El solicitante dispone de Connectia, un producto propio con patrones probados en Node y Vue, con mejoras marcadas [MEJORAR].</p><p><strong>Decisión.</strong> Node.js 20 LTS (ESM) con Express 4; MongoDB 7 en replica set con Mongoose 8; Vue 3.5 + Vite + Pinia + Vue Router + Tailwind; Zod para validación compartida; Redis + BullMQ para colas; <code>vite-plugin-pwa</code> e IndexedDB para la PWA. Se reutilizan los patrones de Connectia aplicando sus correcciones.</p><p><strong>Alternativas consideradas.</strong> .NET + Azure + SQL Server (DFA): descartada por DEC-001. Biblioteca OpenIddict propuesta en DFA M1: reemplazada por una biblioteca OIDC sobre Node (CTR-NFR-11). Validación manual de Connectia: reemplazada por Zod (CTR-NFR-05).</p><p><strong>Consecuencias.</strong> Monorepo JavaScript único (<code>apps/</code>, <code>packages/</code>, <code>infra/</code>) con esquemas compartidos entre backend y frontends. Las transacciones multidocumento exigen replica set también en local y CI. MongoDB no ofrece aritmética decimal en la aplicación, lo que obliga a ADR-017. Los defectos heredados de Connectia (firma HS256, schedulers con <code>setInterval</code>, archivos en disco público) se corrigen en ADR-026, ADR-014 y ADR-035.</p><h4 id="adr-002-—-monolito-modular-con-fronteras-estrictas" tabindex="-1">ADR-002 — Monolito modular con fronteras estrictas <a class="header-anchor" href="#adr-002-—-monolito-modular-con-fronteras-estrictas" aria-label="Permalink to &quot;ADR-002 — Monolito modular con fronteras estrictas&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-003, vigente)</td></tr><tr><td>Origen</td><td>DEC-003; maestra §5.3 ARQ-01; RF-PLA-004 a RF-PLA-007; ARQ-PLA-01 a ARQ-PLA-06 y ARQ-PLA-12; RNF-NFR-240</td></tr></tbody></table><p><strong>Contexto.</strong> El producto abarca 26 módulos de dominio y transversales con un equipo acotado y desarrollo asistido por IA. Se necesitan fronteras claras sin el costo operativo de muchos servicios distribuidos.</p><p><strong>Decisión.</strong> Un único código desplegado como un proceso API y N procesos worker (ARQ-PLA-01). Cada módulo vive en <code>apps/api/src/modules/&amp;lt;cod&gt;/</code> con plantilla fija, declara un <code>manifest.js</code> y es dueño exclusivo de sus colecciones. Otros módulos solo usan su <code>index.js</code> (comandos síncronos) o sus eventos. Grafo de dependencias acíclico verificado por <code>check:boundaries</code>; prohibido <code>$lookup</code> a colecciones de otro módulo (ARQ-PLA-04).</p><p><strong>Alternativas consideradas.</strong> Separación en bases o servidores por módulo: descartada (ARQ-PLA-05). Event sourcing completo: descartado; se usa estado actual + auditoría + outbox (ARQ-PLA-06). Microservicios desde el inicio <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Un solo despliegue y una sola base simplifican la operación y las transacciones. El riesgo de erosión de fronteras (RA-02 de <code>02-arquitectura-c4.md</code>) se controla en CI. Si un módulo necesita escalar aparte, se extrae primero su worker o cola (ARQ-PLA-12).</p><h4 id="adr-003-—-despliegue-en-contenedores-agnostico-de-nube" tabindex="-1">ADR-003 — Despliegue en contenedores agnóstico de nube <a class="header-anchor" href="#adr-003-—-despliegue-en-contenedores-agnostico-de-nube" aria-label="Permalink to &quot;ADR-003 — Despliegue en contenedores agnóstico de nube&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-004, vigente)</td></tr><tr><td>Origen</td><td>DEC-004; RF-PLA-013; RNF-NFR-171, RNF-NFR-245; RNF-PLA-008, RNF-PLA-009; CTR-NFR-08</td></tr></tbody></table><p><strong>Contexto.</strong> Se busca evitar la dependencia de un proveedor de nube y poder operar en otro proveedor o en infraestructura propia.</p><p><strong>Decisión.</strong> Imágenes Docker inmutables (<code>api</code>, <code>worker</code>, <code>admin</code>, <code>pwa</code>, <code>landing</code>) desde un Dockerfile multi-stage, promovidas por digest entre ambientes. Servicios de nube consumidos detrás de adaptadores (almacenamiento S3-compatible, KMS y secretos detrás de interfaz, colas sobre Redis). AWS es la referencia. Infraestructura como código con detección de deriva semanal.</p><p><strong>Alternativas consideradas.</strong> Despliegue por SSH con <code>git reset --hard</code> y <code>.env</code> a mano (Connectia §2.8): descartado (CTR-NFR-08, RNF-PLA-009). Servicios propietarios no sustituibles (funciones sin servidor, bases propietarias) <em>(alternativa de análisis, no registrada en la especificación)</em>: descartados por DEC-004.</p><p><strong>Consecuencias.</strong> Portabilidad a costa de no aprovechar servicios gestionados exclusivos. Quedan a definir el orquestador (ECS Fargate o EKS), la herramienta de IaC (Terraform o CDK) y si MongoDB es Atlas sobre AWS o autogestionado (<code>02-arquitectura-c4.md</code> §9). La dependencia de KMS y Secrets Manager se acota con interfaces agnósticas (RA-07).</p><h4 id="adr-004-—-region-de-alojamiento-aws-sa-east-1" tabindex="-1">ADR-004 — Región de alojamiento AWS sa-east-1 <a class="header-anchor" href="#adr-004-—-region-de-alojamiento-aws-sa-east-1" aria-label="Permalink to &quot;ADR-004 — Región de alojamiento AWS sa-east-1&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-062, vigente)</td></tr><tr><td>Origen</td><td>DEC-062; PA-PLA-01; PA-NFR-05; RNF-NFR-105; RF-PLA-157; RF-NFR-013</td></tr></tbody></table><p><strong>Contexto.</strong> Los datos personales de socios argentinos se alojan fuera del país si se usa una región de nube pública. Se requiere baja latencia regional y cumplimiento de la Ley 25.326 sobre transferencias internacionales.</p><p><strong>Decisión.</strong> Producción en AWS sa-east-1 (San Pablo), con cláusulas contractuales de transferencia internacional según la AAIP, informadas en el aviso de privacidad y en el registro de subencargados. La región se declara por tenant en el contrato y todos sus datos y backups residen en ella.</p><p><strong>Alternativas consideradas.</strong> (PA-PLA-01) B: AWS us-east-1, menor costo y mayor latencia y exigencia contractual. C: proveedor con centro de datos en Argentina para la base y AWS para el resto, más soberanía y mayor complejidad operativa.</p><p><strong>Consecuencias.</strong> Transferencia internacional permanente que exige el registro de subencargados (incluidos los de observabilidad e IA). La región secundaria de recuperación ante desastre y la cuenta de backups quedan a definir; su elección debe respetar las mismas garantías.</p><h4 id="adr-005-—-continuidad-replica-set-multizona-pitr-y-restauracion-por-tenant" tabindex="-1">ADR-005 — Continuidad: replica set multizona, PITR y restauración por tenant <a class="header-anchor" href="#adr-005-—-continuidad-replica-set-multizona-pitr-y-restauracion-por-tenant" aria-label="Permalink to &quot;ADR-005 — Continuidad: replica set multizona, PITR y restauración por tenant&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-063, vigente)</td></tr><tr><td>Origen</td><td>DEC-063; PA-PLA-02/03; RNF-NFR-030 a RNF-NFR-049; RF-PLA-118 a RF-PLA-125; RN-NFR-016</td></tr></tbody></table><p><strong>Contexto.</strong> Las cooperativas facturan y cobran en días críticos; perder cobros del día o restaurar a todos los tenants por el error de uno es inaceptable en una base compartida.</p><p><strong>Decisión.</strong> Disponibilidad 99,5 % mensual; RPO ≤ 15 min; RTO ≤ 4 h por tenant y ≤ 8 h de plataforma completa. MongoDB en replica set de 3 nodos en 3 zonas con <code>writeConcern: majority</code>; PITR continuo con snapshots diarios, semanales y mensuales; backup lógico diario por tenant; restauración selectiva en un cluster aislado con diferencia y aplicación controlada; conciliación con ARCA, pasarelas y mensajería antes de reanudar; backups en cuenta separada con claves KMS propias; ensayos periódicos.</p><p><strong>Alternativas consideradas.</strong> (PA-PLA-02) B: RPO y RTO de 24 h, más barato y con riesgo de perder los cobros del día. C: RPO de 1 min y RTO de 1 h, que requiere multirregión activa de alto costo.</p><p><strong>Consecuencias.</strong> La restauración no revierte efectos externos ya confirmados (RN-NFR-016) ni la auditoría (RF-PLA-124) y reaplica las supresiones posteriores (ver ADR-049). La recuperación regional tiene objetivos distintos (RPO ≤ 1 h, RTO ≤ 24 h, RNF-NFR-046). Costo de almacenamiento y de ensayos mensuales y trimestrales.</p><h4 id="adr-006-—-design-system-propio-sin-librerias-de-interfaz-de-terceros" tabindex="-1">ADR-006 — Design system propio sin librerías de interfaz de terceros <a class="header-anchor" href="#adr-006-—-design-system-propio-sin-librerias-de-interfaz-de-terceros" aria-label="Permalink to &quot;ADR-006 — Design system propio sin librerías de interfaz de terceros&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>T01 §7.1; RT-12 de <code>02-arquitectura-c4.md</code>; maestra §11; RNF-NFR-180, RNF-NFR-182</td></tr></tbody></table><p><strong>Contexto.</strong> Cada cooperativa aplica su marca en tiempo de ejecución y la interfaz debe cumplir WCAG 2.2 AA en dispositivos de gama baja.</p><p><strong>Decisión.</strong> Design system propio en <code>packages/ui</code>, compartido por admin y PWA, sin librerías de componentes, íconos, gráficos ni i18n de terceros. Tokens de marca por tenant con cálculo de contraste al publicar.</p><p><strong>Alternativas consideradas.</strong> Librerías de componentes de terceros <em>(alternativa de análisis, no registrada en la especificación)</em>: descartadas por T01 §7.1.</p><p><strong>Consecuencias.</strong> Mayor esfuerzo inicial en O0; control total de accesibilidad, tamaño de paquete (RNF-NFR-008) y superficie de dependencias (menor exposición de cadena de suministro).</p><h4 id="adr-007-—-configuracion-tipada-y-versionada-y-diccionario-de-textos" tabindex="-1">ADR-007 — Configuración tipada y versionada y diccionario de textos <a class="header-anchor" href="#adr-007-—-configuracion-tipada-y-versionada-y-diccionario-de-textos" aria-label="Permalink to &quot;ADR-007 — Configuración tipada y versionada y diccionario de textos&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §5.3 ARQ-05 y ARQ-07; ARQ-PLA-08; RNF-NFR-028, RNF-NFR-192, RNF-NFR-256; RN-NFR-027</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop dispersa su comportamiento en miles de variables y constantes; cada cooperativa necesita reglas y textos propios sin cambios de código.</p><p><strong>Decisión.</strong> Configuración tipada, versionada y publicada (T04), con caché invalidada por evento en ≤ 60 s y reversión a la versión anterior sin pérdida de datos operativos. Ningún texto fijo en la interfaz: claves <code>dict:&amp;lt;clave&gt;</code> con texto base de respaldo y personalización por tenant.</p><p><strong>Alternativas consideradas.</strong> Constantes en código y variables sin tipo heredadas de ProCoop: descartadas (ARQ-05).</p><p><strong>Consecuencias.</strong> Toda regla configurable requiere esquema, validación y versión; las cachés de configuración no contienen datos personales (RNF-NFR-028).</p><h4 id="adr-008-—-extensibilidad-acotada-sin-ejecucion-dinamica-de-codigo" tabindex="-1">ADR-008 — Extensibilidad acotada, sin ejecución dinámica de código <a class="header-anchor" href="#adr-008-—-extensibilidad-acotada-sin-ejecucion-dinamica-de-codigo" aria-label="Permalink to &quot;ADR-008 — Extensibilidad acotada, sin ejecución dinámica de código&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-079, vigente)</td></tr><tr><td>Origen</td><td>DEC-079; PA-WFL-04; RF-PLA-155; RNF-NFR-238; RN-INT-045, RN-INT-046</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop ejecuta procedimientos por nombre, formularios por reflexión y SQL recibido en tiempo de ejecución, lo que abre la puerta a inyección y ejecución arbitraria.</p><p><strong>Decisión.</strong> El tenant ajusta plantillas de plataforma en puntos de extensión y crea trámites nuevos solo de tipo &quot;solicitud genérica&quot; que terminan en tarea o caso. No existen modos por línea de comandos ni ejecución de funciones por nombre; cada proceso batch es un job registrado. Prohibida la invocación dinámica de código a partir de datos.</p><p><strong>Alternativas consideradas.</strong> (PA-WFL-04) B: diseñador libre con acciones tipadas y nodos obligatorios por dominio. C: solo plantillas de plataforma sin edición.</p><p><strong>Consecuencias.</strong> Menor flexibilidad para el tenant; superficie de ataque acotada y comportamiento verificable en pruebas.</p><h3 id="_2-2-multitenancy-y-aislamiento" tabindex="-1">2.2 Multitenancy y aislamiento <a class="header-anchor" href="#_2-2-multitenancy-y-aislamiento" aria-label="Permalink to &quot;2.2 Multitenancy y aislamiento&quot;">​</a></h3><h4 id="adr-009-—-base-de-datos-unica-compartida-con-tenantid" tabindex="-1">ADR-009 — Base de datos única compartida con <code>tenantId</code> <a class="header-anchor" href="#adr-009-—-base-de-datos-unica-compartida-con-tenantid" aria-label="Permalink to &quot;ADR-009 — Base de datos única compartida con `tenantId`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-002, vigente)</td></tr><tr><td>Origen</td><td>DEC-002; maestra §6; RF-PLA-016 a RF-PLA-018; RN-DAT-001; RNF-NFR-025; CTR-NFR-02, CTR-NFR-11</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop usa una base por cooperativa elegida por archivo local; DFA proponía mantenerla. El solicitante pidió explícitamente &quot;multitenant tradicional, una base de datos única con todo pero con identificadores de a qué cooperativa pertenecés&quot;.</p><p><strong>Decisión.</strong> Una sola base MongoDB compartida por ambiente; todo documento de negocio lleva <code>tenantId</code> (ObjectId, obligatorio, inmutable); todo índice compuesto, incluidos únicos, parciales, TTL y geoespaciales, empieza por <code>tenantId</code>.</p><p><strong>Alternativas consideradas.</strong> Base por cooperativa (ProCoop, DFA M1): descartada (CTR-NFR-02). Base o esquema por tenant con enrutamiento por conexión <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Operación, migraciones e índices únicos para todos los tenants. El riesgo principal es la fuga entre tenants (RA-01), que se compensa con ADR-010 y con el cifrado de campo por tenant de ADR-033 (CTR-NFR-02). La restauración de un tenant requiere backup lógico por tenant (ADR-005) y el vecino ruidoso requiere ADR-012.</p><h4 id="adr-010-—-aislamiento-de-tenant-forzado-en-todas-las-superficies" tabindex="-1">ADR-010 — Aislamiento de tenant forzado en todas las superficies <a class="header-anchor" href="#adr-010-—-aislamiento-de-tenant-forzado-en-todas-las-superficies" aria-label="Permalink to &quot;ADR-010 — Aislamiento de tenant forzado en todas las superficies&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>DEC-002; RF-PLA-019 a RF-PLA-034; RN-NFR-001, RN-NFR-002; RN-DAT-002; RNF-NFR-148, RNF-NFR-149, RNF-NFR-238; RNF-NFR-115, RNF-NFR-133</td></tr></tbody></table><p><strong>Contexto.</strong> Con base compartida, una consulta sin filtro o un identificador manipulado expone datos de otra cooperativa. La disciplina del programador no alcanza como control.</p><p><strong>Decisión.</strong> El tenant sale del claim <code>tid</code> del token o del contexto del job, nunca de un header, query o body. Un contexto <code>AsyncLocalStorage</code> propaga <code>tenantId</code>, actor, <code>requestId</code>, <code>correlationId</code> y <code>supportGrantId</code>. El plugin de tenancy de Mongoose inyecta el filtro en toda operación (incluidos <code>$lookup</code>, <code>$unionWith</code>, <code>$graphLookup</code>, <code>bulkWrite</code> e <code>insert*</code>) y lanza error si falta el contexto. El único escape es <code>runAsPlatform</code> con motivo y auditoría. Jobs, eventos, objetos, claves de Redis, exportaciones, búsquedas, IA, logs y webhooks llevan el tenant. Un acceso cruzado responde 404, se audita y alerta SEV2. Una suite de aislamiento con dos tenants recorre todas las rutas y jobs y bloquea el merge; una prueba de mutación verifica que deshabilitar el plugin rompe la suite.</p><p><strong>Alternativas consideradas.</strong> Filtro por convención en cada consulta, sin plugin <em>(alternativa de análisis, no registrada en la especificación)</em>. Tenant informado por header o selector del cliente: descartado (RN-NFR-001).</p><p><strong>Consecuencias.</strong> Toda colección nueva declara su tenancy o el arranque falla (RF-PLA-023). Costo de mantenimiento de la suite y del lint de agregaciones. Detalle de controles en <code>28-modelo-amenazas-seguridad.md</code> §6.</p><h4 id="adr-011-—-tenant-platform-y-colecciones-globales-en-lista-blanca" tabindex="-1">ADR-011 — Tenant <code>PLATFORM</code> y colecciones globales en lista blanca <a class="header-anchor" href="#adr-011-—-tenant-platform-y-colecciones-globales-en-lista-blanca" aria-label="Permalink to &quot;ADR-011 — Tenant `PLATFORM` y colecciones globales en lista blanca&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RF-PLA-023, RF-PLA-036 a RF-PLA-040; DEC-065; PA-PLA-08; T05 §7.1.2 y §7.1.3</td></tr></tbody></table><p><strong>Contexto.</strong> El operador del SaaS necesita catálogos globales, facturar el servicio y operar la plataforma sin romper el modelo de tenancy.</p><p><strong>Decisión.</strong> Existe el tenant técnico <code>PLATFORM</code>, creado por migración idempotente, que aloja catálogos de plataforma de solo lectura para los tenants y usa los módulos funcionales para su propia gestión (incluida la facturación del SaaS con M05 desde O5). Solo las colecciones de una lista blanca no llevan <code>tenantId</code>; cualquier otra sin <code>tenantId</code> es defecto bloqueante.</p><p><strong>Alternativas consideradas.</strong> (PA-PLA-08) B: sistema externo de facturación permanente. C: facturación manual sin prefactura. Colecciones globales sin lista cerrada <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Pertenecer a <code>PLATFORM</code> no da acceso a datos de negocio de los tenants (RF-PLA-038); ese acceso pasa por ADR-030. La lista blanca difiere entre T01 y T05 (ver sección 4, OBS-ADR-03).</p><h4 id="adr-012-—-colas-por-clase-de-carga-y-cuotas-por-tenant" tabindex="-1">ADR-012 — Colas por clase de carga y cuotas por tenant <a class="header-anchor" href="#adr-012-—-colas-por-clase-de-carga-y-cuotas-por-tenant" aria-label="Permalink to &quot;ADR-012 — Colas por clase de carga y cuotas por tenant&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-075, vigente)</td></tr><tr><td>Origen</td><td>DEC-075; PA-NFR-03; RN-NFR-025; RF-PLA-129 a RF-PLA-135; RNF-NFR-020 a RNF-NFR-024, RNF-NFR-029; DT-01 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> El perfil de capacidad va de 25.000 a 150.000 suministros por tenant, con diseño para 100 tenants y crecimiento a 300 sin rediseño. Un lote de un tenant grande no puede degradar la caja de otro.</p><p><strong>Decisión.</strong> Colas BullMQ por clase de carga (<code>interactive</code>, <code>integration</code>, <code>events</code>, <code>notifications</code>, <code>batch</code>, <code>export</code>, <code>ai</code>, <code>maintenance</code>) con prioridad y concurrencia global y por tenant; réplicas de workers separadas por cola; rate limiting y cuotas por tenant configurables por plan; lecturas pesadas en secundarios; rechazo temprano de <code>batch</code> y <code>bulk</code> ante sobrecarga.</p><p><strong>Alternativas consideradas.</strong> (PA-NFR-03) B: tenant grande de 50.000 y 50 tenants, con riesgo de rediseño temprano. C: tenant grande de 500.000, que sobredimensiona. Cola única FIFO o workers dedicados por tenant <em>(alternativas de análisis, no registradas en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Las clases de cola y la concurrencia batch por tenant difieren entre T01 y T08 (DT-01 del documento C4); debe unificarse antes de O0.</p><h4 id="adr-013-—-copia-entre-tenants-y-plantillas-de-plataforma-sin-datos-personales" tabindex="-1">ADR-013 — Copia entre tenants y plantillas de plataforma sin datos personales <a class="header-anchor" href="#adr-013-—-copia-entre-tenants-y-plantillas-de-plataforma-sin-datos-personales" aria-label="Permalink to &quot;ADR-013 — Copia entre tenants y plantillas de plataforma sin datos personales&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-025 y DEC-026, vigentes)</td></tr><tr><td>Origen</td><td>DEC-025, DEC-026; RF-PLA-164, RF-PLA-165; RF-INT-008; RN-NFR-013</td></tr></tbody></table><p><strong>Contexto.</strong> Las cooperativas quieren reutilizar configuraciones de servicios entre sí y la plataforma quiere ofrecer plantillas, sin romper el aislamiento.</p><p><strong>Decisión.</strong> La copia de configuración entre tenants requiere autorización explícita del tenant origen. Las plantillas de plataforma no incluyen precios ni condiciones reguladas. Ninguna copia traslada datos personales, credenciales, secretos, identificadores externos ni estados.</p><p><strong>Alternativas consideradas.</strong> Copia libre por la plataforma sin consentimiento del origen <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> La copia se implementa como operación de plataforma auditada (<code>runAsPlatform</code> con motivo) con lista blanca de campos copiables.</p><h3 id="_2-3-consistencia-datos-y-dinero" tabindex="-1">2.3 Consistencia, datos y dinero <a class="header-anchor" href="#_2-3-consistencia-datos-y-dinero" aria-label="Permalink to &quot;2.3 Consistencia, datos y dinero&quot;">​</a></h3><h4 id="adr-014-—-outbox-transaccional-inbox-idempotente-y-workers-bullmq" tabindex="-1">ADR-014 — Outbox transaccional, inbox idempotente y workers BullMQ <a class="header-anchor" href="#adr-014-—-outbox-transaccional-inbox-idempotente-y-workers-bullmq" aria-label="Permalink to &quot;ADR-014 — Outbox transaccional, inbox idempotente y workers BullMQ&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-003, vigente)</td></tr><tr><td>Origen</td><td>DEC-003; RF-PLA-008 a RF-PLA-011; T01 §7.6; RNF-NFR-013, RNF-NFR-014, RNF-NFR-214, RNF-NFR-215; RN-NFR-024; CTR-NFR-06</td></tr></tbody></table><p><strong>Contexto.</strong> Los efectos entre módulos (factura → cuenta corriente → asiento) deben ocurrir siempre y una sola vez, aunque fallen procesos o redes.</p><p><strong>Decisión.</strong> El cambio de negocio, su evento (<code>outboxEvents</code>) y su auditoría se escriben en la misma transacción. Un relay único por elección de líder (lock en Redis) lee por change stream con sondeo de respaldo y encola un job por consumidor (<code>jobId = &amp;lt;eventId&gt;:&amp;lt;consumer&gt;</code>). Cada consumidor aplica su efecto e inserta <code>inboxReceipts</code> en la misma transacción. Jobs <code>&amp;lt;modulo&gt;:&amp;lt;proceso&gt;</code> idempotentes, reanudables, con progreso en <code>jobRuns</code>; agotados los reintentos van a <code>deadLetters</code> con alerta.</p><p><strong>Alternativas consideradas.</strong> Schedulers con <code>setInterval</code> dentro del API (Connectia): descartados (CTR-NFR-06). Event sourcing completo: descartado (ARQ-PLA-06). Publicar a la cola después del commit sin outbox <em>(alternativa de análisis, no registrada en la especificación)</em>: pierde eventos ante caídas.</p><p><strong>Consecuencias.</strong> Entrega al menos una vez: todo consumidor debe ser idempotente. Latencia de outbox p95 ≤ 5 s con alerta a 60 s (RNF-NFR-014). El relay único es un punto de riesgo (RA-05) mitigado con elección de líder y reprocesamiento.</p><h4 id="adr-015-—-redis-no-es-fuente-de-verdad" tabindex="-1">ADR-015 — Redis no es fuente de verdad <a class="header-anchor" href="#adr-015-—-redis-no-es-fuente-de-verdad" aria-label="Permalink to &quot;ADR-015 — Redis no es fuente de verdad&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-NFR-041; RNF-NFR-023; RF-PLA-026; RNF-PLA-015</td></tr></tbody></table><p><strong>Contexto.</strong> Redis aloja colas, caché, rate limiting, locks, circuit breakers y tokens de integración; su pérdida no puede perder trabajo ni duplicar efectos.</p><p><strong>Decisión.</strong> Todo estado de jobs, progreso y resultado se persiste en MongoDB. Ante pérdida total de Redis se reencola desde Mongo en ≤ 15 min sin duplicar efectos. Claves con prefijo <code>t:&amp;lt;tenantId&gt;:</code> o <code>p:</code>; prohibido cachear respuestas con datos personales en caché compartida.</p><p><strong>Alternativas consideradas.</strong> Redis con persistencia como almacén de estado <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> API y workers sin estado en memoria; escalado horizontal sin afinidad de sesión. Redis con réplica y failover para disponibilidad, no para durabilidad.</p><h4 id="adr-016-—-almacen-analitico-en-un-miembro-dedicado-del-replica-set" tabindex="-1">ADR-016 — Almacén analítico en un miembro dedicado del replica set <a class="header-anchor" href="#adr-016-—-almacen-analitico-en-un-miembro-dedicado-del-replica-set" aria-label="Permalink to &quot;ADR-016 — Almacén analítico en un miembro dedicado del replica set&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (asumida, DEC-072)</td></tr><tr><td>Origen</td><td>PA-BIA-01; T10 §7.15; RF-PLA-035; RNF-NFR-022, RNF-NFR-106</td></tr></tbody></table><p><strong>Contexto.</strong> BI y exportaciones pesadas no deben afectar la facturación ni la atención, y DEC-001/DEC-004 fijan MongoDB y despliegue agnóstico.</p><p><strong>Decisión.</strong> Base lógica <code>&amp;lt;db&gt;_analytics</code> con colecciones <code>bi_*</code> proyectadas desde eventos, leída desde un miembro oculto del replica set con etiqueta <code>analytics</code> (prioridad 0). Lecturas pesadas con <code>secondaryPreferred</code> y desfase máximo de 90 s, mostrando la fecha de corte.</p><p><strong>Alternativas consideradas.</strong> (PA-BIA-01) B: cluster MongoDB separado para analítica, más aislamiento y más costo. C: sin almacén, todo BI sobre secundarios operativos, con riesgo en horas pico y sin historización.</p><p><strong>Consecuencias.</strong> Sin tecnología nueva. Los cubos trabajan con seudónimos y suprimen celdas reidentificables (RNF-NFR-106). El miembro analítico comparte hardware de replicación y requiere dimensionamiento propio (a definir).</p><h4 id="adr-017-—-dinero-en-decimal128-y-decimal-js" tabindex="-1">ADR-017 — Dinero en <code>Decimal128</code> y <code>decimal.js</code> <a class="header-anchor" href="#adr-017-—-dinero-en-decimal128-y-decimal-js" aria-label="Permalink to &quot;ADR-017 — Dinero en `Decimal128` y `decimal.js`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §13; RN-NFR-005, RN-NFR-006; RN-DAT-005; T05 §7.1.7; RNF-NFR-152, RNF-NFR-200 a RNF-NFR-206; RT-05</td></tr></tbody></table><p><strong>Contexto.</strong> La exactitud económica es el segundo atributo de calidad prioritario: cero diferencias de centavos entre comprobante, cuenta corriente y contabilidad. ProCoop usa <code>money</code>/<code>float</code> en SQL Server.</p><p><strong>Decisión.</strong> Importes, tasas, alícuotas, precios y cantidades facturables en <code>Decimal128</code> en Mongo y <code>decimal.js</code> en <code>packages/shared/money</code> (precisión 34). En la API viajan como cadena decimal con moneda. Redondeo explícito por concepto; distribuciones por método de mayor resto. Regla SAST/ESLint que prohíbe <code>Number</code>, <code>parseFloat</code>, <code>toFixed</code> y <code>Math.round</code> en dominio monetario.</p><p><strong>Alternativas consideradas.</strong> <code>Number</code> de JavaScript: prohibido (RN-NFR-005). Enteros en centavos <em>(alternativa de análisis, no registrada en la especificación)</em>: no cubre precios unitarios de 6 decimales ni tasas de 8 (RNF-NFR-202).</p><p><strong>Consecuencias.</strong> Pruebas basadas en propiedades y de mutación sobre <code>money</code>. Agregaciones con <code>$toDecimal</code>. Serialización consistente entre API, eventos y exportaciones.</p><h4 id="adr-018-—-idempotencia-por-idempotency-key-y-claves-naturales" tabindex="-1">ADR-018 — Idempotencia por <code>Idempotency-Key</code> y claves naturales <a class="header-anchor" href="#adr-018-—-idempotencia-por-idempotency-key-y-claves-naturales" aria-label="Permalink to &quot;ADR-018 — Idempotencia por `Idempotency-Key` y claves naturales&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §5.3 ARQ-02 y §13; RN-NFR-007; RNF-NFR-151, RNF-NFR-212 a RNF-NFR-219, RNF-NFR-226; RF-INT-037</td></tr></tbody></table><p><strong>Contexto.</strong> Reintentos de red, doble clic, reenvío de webhooks y reprocesamiento de archivos de rendición pueden duplicar cobros o comprobantes.</p><p><strong>Decisión.</strong> <code>Idempotency-Key</code> (UUID generado por el cliente) obligatorio en todo <code>POST</code>/<code>PATCH</code> económico o de integración; un reintento devuelve el mismo resultado. Claves naturales únicas como segunda barrera (por ejemplo <code>{tenantId, provider, externalPaymentId}</code>). Consumidores con <code>inboxReceipts</code>; jobs con ID determinista; offline con <code>clientMutationId</code>; archivos deduplicados por hash; operaciones de integración por <code>tenantId + operationType + businessKey</code>.</p><p><strong>Alternativas consideradas.</strong> Deduplicación solo por clave natural <em>(alternativa de análisis, no registrada en la especificación)</em>: no cubre operaciones sin clave natural previa.</p><p><strong>Consecuencias.</strong> La clave se registra en logs solo como hash (RNF-NFR-121). La colección que guarda las claves tiene definiciones duplicadas entre anexos (CTR-NFR-22, ver OBS-ADR-05).</p><h4 id="adr-019-—-transacciones-multidocumento-y-control-optimista" tabindex="-1">ADR-019 — Transacciones multidocumento y control optimista <a class="header-anchor" href="#adr-019-—-transacciones-multidocumento-y-control-optimista" aria-label="Permalink to &quot;ADR-019 — Transacciones multidocumento y control optimista&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-NFR-210, RNF-NFR-211, RNF-NFR-216, RNF-NFR-220; RF-IAM-139; T05 §7.1.4 y §7.1.15; RF-PLA-008; ARQ-PLA-03</td></tr></tbody></table><p><strong>Contexto.</strong> Una operación económica toca varios documentos (factura, ítems, cuenta corriente, asiento, auditoría, outbox) y varios usuarios editan las mismas fichas.</p><p><strong>Decisión.</strong> Transacciones multidocumento con <code>writeConcern: majority</code> en toda operación que toque más de un documento económico. Campo <code>version</code> en todo documento de negocio; las actualizaciones condicionan <code>{_id, tenantId, version}</code> y un conflicto devuelve 409 problem+json. Exclusión mutua de procesos sobre el mismo universo con lease en Mongo; recursos escasos reservados con operación atómica condicional.</p><p><strong>Alternativas consideradas.</strong> Bloqueos de filas al estilo ProCoop (<code>BLOQUEO_FILAS</code>, <code>GetMaxValue_Boqueo</code>): descartados (RN-INT-064, RF-IAM-140 los reemplaza por aviso de edición concurrente).</p><p><strong>Consecuencias.</strong> Requiere replica set en todos los ambientes. El alcance de una transacción entre módulos está descripto de forma distinta en T01 y T05 (ver OBS-ADR-04).</p><h4 id="adr-020-—-documentos-economicos-inmutables-y-anulacion-por-contrapartida" tabindex="-1">ADR-020 — Documentos económicos inmutables y anulación por contrapartida <a class="header-anchor" href="#adr-020-—-documentos-economicos-inmutables-y-anulacion-por-contrapartida" aria-label="Permalink to &quot;ADR-020 — Documentos económicos inmutables y anulación por contrapartida&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RN-DAT-004; T05 §7.1.6; RN-NFR-017; RNF-NFR-205; CTR-NFR-17</td></tr></tbody></table><p><strong>Contexto.</strong> Facturas, recibos, asientos y movimientos tienen valor fiscal y contable; ProCoop usa tablas espejo de anulación.</p><p><strong>Decisión.</strong> Los documentos económicos no se borran ni se editan después de emitidos; se corrigen con documentos de signo contrario (<code>reversalOf</code>/<code>reversedBy</code>). El modelo bloquea <code>deleteOne</code>/<code>deleteMany</code> y el usuario de base de la aplicación no tiene privilegio <code>remove</code> sobre esas colecciones (rol <code>appEconomicWriter</code>); validador <code>$jsonSchema</code> en base.</p><p><strong>Alternativas consideradas.</strong> Tablas espejo <code>ANUFAC</code>, <code>ANUPAG_SOC</code> y similares de ProCoop: descartadas; se migran como documentos anulados.</p><p><strong>Consecuencias.</strong> La supresión de datos personales no borra documentos económicos: bloquea y anonimiza los campos no obligatorios al vencer la conservación (CTR-NFR-17, ADR-049).</p><h4 id="adr-021-—-instantes-en-utc-y-fechas-de-negocio-en-la-zona-del-tenant" tabindex="-1">ADR-021 — Instantes en UTC y fechas de negocio en la zona del tenant <a class="header-anchor" href="#adr-021-—-instantes-en-utc-y-fechas-de-negocio-en-la-zona-del-tenant" aria-label="Permalink to &quot;ADR-021 — Instantes en UTC y fechas de negocio en la zona del tenant&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RN-NFR-018; RN-DAT-006; RNF-NFR-138, RNF-NFR-194, RNF-NFR-228; RF-IAM-046; RNF-PLA-007; CTR-NFR-19</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop controla el desfase de reloj del puesto y usa fechas locales; en SaaS la hora del cliente no es confiable para auditoría ni vencimientos.</p><p><strong>Decisión.</strong> Instantes en UTC con hora del servidor sincronizada por NTP; fechas de negocio como <code>YYYY-MM-DD</code> interpretadas en la zona del tenant (<code>America/Argentina/Cordoba</code> por defecto); períodos <code>YYYY-MM</code>. La hora del dispositivo de campo se guarda como dato declarado.</p><p><strong>Alternativas consideradas.</strong> Control de desfase de reloj del puesto (ProCoop): reemplazado (CTR-NFR-19).</p><p><strong>Consecuencias.</strong> Las marcas de auditoría y sesión no dependen del cliente; los cálculos de vencimiento son reproducibles.</p><h4 id="adr-022-—-personas-juridicas-por-tenant-y-cuenta-corriente-por-entidad" tabindex="-1">ADR-022 — Personas jurídicas por tenant y cuenta corriente por entidad <a class="header-anchor" href="#adr-022-—-personas-juridicas-por-tenant-y-cuenta-corriente-por-entidad" aria-label="Permalink to &quot;ADR-022 — Personas jurídicas por tenant y cuenta corriente por entidad&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-064 y DEC-087, vigentes)</td></tr><tr><td>Origen</td><td>DEC-064; PA-PLA-14; DEC-087 (PA-DAT-01); RN-DAT-008; T05 §7.1.10</td></tr></tbody></table><p><strong>Contexto.</strong> Algunas cooperativas operan con más de un CUIT (equivalente a <code>EMPRESAS</code> de ProCoop), con emisión, contabilidad y sueldos separados.</p><p><strong>Decisión.</strong> <code>legalEntities</code> del tenant (T04) y <code>legalEntityId</code> obligatorio en documentos económicos y fiscales desde O0. Una cuenta corriente por titular y por entidad jurídica; un cobro de caja puede cubrir varias entidades con un recibo por entidad.</p><p><strong>Alternativas consideradas.</strong> (PA-PLA-14) B: un tenant por CUIT. C: solo para sueldos. (PA-DAT-01) B: cuenta corriente única con recibo de la entidad principal. C: cobro separado por entidad.</p><p><strong>Consecuencias.</strong> Índices únicos de numeración por entidad y punto de venta; certificados y conexiones ARCA por entidad; mayor complejidad de imputación en caja.</p><h3 id="_2-4-contratos-de-api-y-eventos" tabindex="-1">2.4 Contratos de API y eventos <a class="header-anchor" href="#_2-4-contratos-de-api-y-eventos" aria-label="Permalink to &quot;2.4 Contratos de API y eventos&quot;">​</a></h3><h4 id="adr-023-—-contrato-de-api-zod-rfc-9457-y-paginacion-uniforme" tabindex="-1">ADR-023 — Contrato de API: Zod, RFC 9457 y paginación uniforme <a class="header-anchor" href="#adr-023-—-contrato-de-api-zod-rfc-9457-y-paginacion-uniforme" aria-label="Permalink to &quot;ADR-023 — Contrato de API: Zod, RFC 9457 y paginación uniforme&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §13; RF-PLA-014, RF-PLA-015; RNF-NFR-082, RNF-NFR-083, RNF-NFR-091, RNF-NFR-201, RNF-NFR-247; RT-07; CTR-NFR-05</td></tr></tbody></table><p><strong>Contexto.</strong> Cinco familias de rutas (<code>/api</code>, <code>/api/admin</code>, <code>/api/platform</code>, <code>/api/public/&amp;lt;tenantSlug&gt;</code>, <code>/api/v1/ext</code>) consumidas por tres frontends, terceros y la IA de desarrollo requieren un contrato uniforme y seguro.</p><p><strong>Decisión.</strong> Validación con esquemas Zod <code>.strict()</code> compartidos en <code>packages/shared/schemas</code> para <code>params</code>, <code>query</code>, headers relevantes y <code>body</code> de toda ruta; DTO de salida por rol; errores RFC 9457 (<code>application/problem+json</code>) con <code>requestId</code>, sin stack ni detalles internos en 5xx; paginación <code>{items, total, page, size}</code> con tope; OpenAPI generado desde los esquemas y verificado en cada PR.</p><p><strong>Alternativas consideradas.</strong> Validación manual de Connectia: reemplazada (CTR-NFR-05). Formato de error propio <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Front y back comparten tipos; los cambios incompatibles se detectan por diff semántico de OpenAPI (RNF-NFR-143).</p><h4 id="adr-024-—-versionado-de-api-externa-y-de-eventos" tabindex="-1">ADR-024 — Versionado de API externa y de eventos <a class="header-anchor" href="#adr-024-—-versionado-de-api-externa-y-de-eventos" aria-label="Permalink to &quot;ADR-024 — Versionado de API externa y de eventos&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-NFR-174 a RNF-NFR-179; RF-PLA-153; PA-NFR-18; T11 §12.1; DT-08 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> Terceros integran contra <code>/api/v1/ext</code> y los consumidores internos dependen de la forma de los eventos; la PWA puede quedar en caché con una versión anterior.</p><p><strong>Decisión.</strong> API interna sin versión en la ruta pero compatible con el front N-1 durante ≤ 14 días (<code>X-App-Version</code>). API externa versionada en ruta, solo cambios aditivos dentro de una versión mayor, deprecación con encabezados <code>Deprecation</code> y <code>Sunset</code> y aviso previo. Eventos con <code>schemaVersion</code>; un cambio incompatible crea un tipo nuevo o una versión mayor con doble publicación. Documentos con <code>schemaVersion</code> por colección.</p><p><strong>Alternativas consideradas.</strong> Versionado por header <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Catálogo de eventos versionado (T11 §12.4); la convención de nombres de eventos aún no está normalizada entre anexos (DT-08).</p><h3 id="_2-5-identidad-y-acceso" tabindex="-1">2.5 Identidad y acceso <a class="header-anchor" href="#_2-5-identidad-y-acceso" aria-label="Permalink to &quot;2.5 Identidad y acceso&quot;">​</a></h3><h4 id="adr-025-—-identidad-comun-con-pertenencias-privadas-por-tenant" tabindex="-1">ADR-025 — Identidad común con pertenencias privadas por tenant <a class="header-anchor" href="#adr-025-—-identidad-comun-con-pertenencias-privadas-por-tenant" aria-label="Permalink to &quot;ADR-025 — Identidad común con pertenencias privadas por tenant&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §6; RF-IAM-001 a RF-IAM-010; ARQ-PLA-09; T05 §7.1.3 (<code>identities</code>, <code>federatedLinks</code>)</td></tr></tbody></table><p><strong>Contexto.</strong> Una persona puede ser empleada de una cooperativa y socia de otra; ProCoop tiene usuarios por base.</p><p><strong>Decisión.</strong> Una identidad de acceso común por persona (correo verificado como identificador global) con pertenencias privadas por tenant y contexto (<code>staff</code>, <code>portal</code>). Selección de ámbito explícita y verificada en servidor; el cambio de ámbito emite un token nuevo y limpia cachés del cliente. La coincidencia de DNI, CUIT, correo o teléfono nunca crea pertenencias ni fusiona identidades.</p><p><strong>Alternativas consideradas.</strong> Usuario por tenant sin identidad común (modelo ProCoop) <em>(alternativa de análisis, no registrada en la especificación)</em>. Fusión automática por correo o documento: descartada (RF-IAM-006).</p><p><strong>Consecuencias.</strong> <code>identities</code> y <code>federatedLinks</code> son colecciones globales: un tenant no puede consultar ni inferir las pertenencias de una persona en otro (RF-IAM-002).</p><h4 id="adr-026-—-autenticacion-del-personal-y-modelo-de-sesion" tabindex="-1">ADR-026 — Autenticación del personal y modelo de sesión <a class="header-anchor" href="#adr-026-—-autenticacion-del-personal-y-modelo-de-sesion" aria-label="Permalink to &quot;ADR-026 — Autenticación del personal y modelo de sesión&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada con validación pendiente (PA-IAM-13 asumida)</td></tr><tr><td>Origen</td><td>RF-IAM-020 a RF-IAM-023, RF-IAM-033 a RF-IAM-044; RNF-NFR-060 a RNF-NFR-066, RNF-NFR-231, RNF-NFR-232; CTR-NFR-03, CTR-NFR-04, CTR-NFR-20; PA-IAM-11</td></tr></tbody></table><p><strong>Contexto.</strong> Connectia firma tokens con HS256 y un secreto compartido; ProCoop usa contraseñas maestras y derivadas de la fecha.</p><p><strong>Decisión.</strong> Pre-login por subdominio o código sin revelar usuarios. Contraseñas con Argon2id (bcrypt costo ≥ 12 como mínimo heredado) y política NIST. MFA obligatoria para plataforma, T-ADM, T-USR y capabilities sensibles; SMS no admitido para roles de plataforma ni T-ADM; passkeys opcionales. Access JWT de 15 min firmado con EdDSA o ES256 y <code>kid</code>, rotación cada 90 días; refresh opaco rotativo de un solo uso guardado hasheado en <code>sessions</code>, en cookie <code>__Host-</code> <code>HttpOnly; Secure; SameSite=Strict</code>; reutilización de un refresh revoca la familia; revocación efectiva ≤ 60 s; refresh ≤ 12 h para administradores de plataforma. Step-up para acciones sensibles.</p><p><strong>Alternativas consideradas.</strong> HS256 con secreto compartido (Connectia §2.5): reemplazado (CTR-NFR-03). bcrypt como único algoritmo: Argon2id preferido (CTR-NFR-04). Refresh de 30 días para todos: acotado para plataforma (CTR-NFR-20).</p><p><strong>Consecuencias.</strong> El access token vive solo en memoria del front; nada sensible en <code>localStorage</code>. Gestión de claves de firma con rotación y superposición de verificación.</p><h4 id="adr-027-—-ingreso-del-socio-con-contrasena-u-otp-sin-enlace-magico" tabindex="-1">ADR-027 — Ingreso del socio con contraseña u OTP, sin enlace mágico <a class="header-anchor" href="#adr-027-—-ingreso-del-socio-con-contrasena-u-otp-sin-enlace-magico" aria-label="Permalink to &quot;ADR-027 — Ingreso del socio con contraseña u OTP, sin enlace mágico&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-066, vigente)</td></tr><tr><td>Origen</td><td>DEC-066; PA-IAM-01; RF-IAM-024, RF-IAM-026, RF-IAM-048; DEC-043</td></tr></tbody></table><p><strong>Contexto.</strong> Los socios ingresan desde celulares de gama baja; se busca simplicidad sin abrir sesiones en navegadores ajenos.</p><p><strong>Decisión.</strong> DNI o CUIT + contraseña dentro del tenant; OTP de 6 dígitos por correo o SMS habilitable por tenant; sin enlace mágico. La vinculación de un usuario a un titular exige prueba (código de factura + documento, código al contacto o validación presencial) con intentos limitados.</p><p><strong>Alternativas consideradas.</strong> (PA-IAM-01) B: OTP y enlace mágico, con riesgo de sesiones abiertas en navegadores ajenos. C: solo contraseña y federados, con más pedidos de recuperación.</p><p><strong>Consecuencias.</strong> El OTP cuenta como un factor; requiere rate limiting y anti-enumeración estrictos en pre-login, OTP y registro (RNF-NFR-075 a RNF-NFR-077).</p><h4 id="adr-028-—-proveedores-de-identidad-federados-y-cidi-cordoba" tabindex="-1">ADR-028 — Proveedores de identidad federados y CiDi Córdoba <a class="header-anchor" href="#adr-028-—-proveedores-de-identidad-federados-y-cidi-cordoba" aria-label="Permalink to &quot;ADR-028 — Proveedores de identidad federados y CiDi Córdoba&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-067, vigente)</td></tr><tr><td>Origen</td><td>DEC-067; PA-IAM-02; RF-IAM-025, RF-IAM-027 a RF-IAM-029</td></tr></tbody></table><p><strong>Contexto.</strong> CoopOnline ofrece CiDi; el personal de algunas cooperativas usa un proveedor corporativo.</p><p><strong>Decisión.</strong> Mecanismo genérico de proveedor federado en O1; Google OIDC para socios con vínculo explícito; SSO OIDC por tenant para staff con dominios permitidos; CiDi Córdoba habilitable por tenant al publicar el portal (O2) con nivel mínimo 2 para vincular cuentas. Un IdP externo no satisface la política de MFA salvo que declare <code>amr</code>/<code>acr</code> y el tenant lo acepte.</p><p><strong>Alternativas consideradas.</strong> (PA-IAM-02) B: CiDi solo en O2 junto con el portal. C: fuera de alcance hasta que una cooperativa lo pida.</p><p><strong>Consecuencias.</strong> Sin fusión de cuentas por correo; la cadena de confianza incluye a cada IdP habilitado como subencargado o tercero.</p><h4 id="adr-029-—-autorizacion-por-capabilities-en-capas-con-denegacion-por-defecto" tabindex="-1">ADR-029 — Autorización por capabilities en capas con denegación por defecto <a class="header-anchor" href="#adr-029-—-autorizacion-por-capabilities-en-capas-con-denegacion-por-defecto" aria-label="Permalink to &quot;ADR-029 — Autorización por capabilities en capas con denegación por defecto&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §7.1; RF-IAM-060 a RF-IAM-077, RF-IAM-090 a RF-IAM-096; RNF-NFR-090, RNF-NFR-150</td></tr></tbody></table><p><strong>Contexto.</strong> 40 roles en cuatro espacios, alcance por sucursal, zona o cuadrilla, límites de importe y separación de funciones.</p><p><strong>Decisión.</strong> Capability <code>modulo.recurso.accion</code> declarada en código; acceso efectivo = licencia ∩ activación ∩ rol ∩ alcance. Un endpoint sin capability declarada no se monta. Denegaciones explícitas prevalecen; separación de funciones dinámica y estática; autorización de supervisor en el momento o diferida; <code>authzVersion</code> aplica cambios en ≤ 60 s; campos sensibles enmascarados salvo capability específica.</p><p><strong>Alternativas consideradas.</strong> Permisos por pantalla al estilo <code>PERFILES</code> de ProCoop sin capabilities de acción <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Matriz de permisos negativos en CI; explicador de permisos para soporte (RF-IAM-069).</p><h4 id="adr-030-—-acceso-de-soporte-temporal-y-acceso-de-emergencia" tabindex="-1">ADR-030 — Acceso de soporte temporal y acceso de emergencia <a class="header-anchor" href="#adr-030-—-acceso-de-soporte-temporal-y-acceso-de-emergencia" aria-label="Permalink to &quot;ADR-030 — Acceso de soporte temporal y acceso de emergencia&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada con validación pendiente (PA-PLA-05 y PA-IAM-06 asumidas)</td></tr><tr><td>Origen</td><td>RF-PLA-101 a RF-PLA-106; RF-IAM-111, RF-IAM-112; PA-PLA-05; PA-IAM-06; RNF-NFR-237; RN-NFR-004</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop tiene contraseñas maestras; un SaaS debe poder dar soporte sin que el operador vea datos de todas las cooperativas.</p><p><strong>Decisión.</strong> Los roles de plataforma no acceden a datos operativos por defecto. El acceso de soporte es un permiso temporal vinculado a un caso, con alcance mínimo, modo observar (datos personales enmascarados) u operar/configurar (con aprobación del administrador del tenant), vencimiento y revocación; las acciones quedan con <code>actorType: &#39;support&#39;</code> y <code>supportGrantId</code>. Acceso de emergencia para incidentes P1 con doble aprobación de plataforma y notificación inmediata al tenant; acceso de emergencia a infraestructura con SSO + MFA, segundo aprobador, sesión grabada y vigencia ≤ 4 h.</p><p><strong>Alternativas consideradas.</strong> Contraseñas maestras o impersonación sin rastro: descartadas (RN-NFR-004, RF-PLA-103). Acceso permanente de soporte a todas las cooperativas: descartado (RF-PLA-106).</p><p><strong>Consecuencias.</strong> El tenant ve y puede revocar las intervenciones. Las reglas de aprobación del acceso de emergencia no coinciden entre fuentes (ver OBS-ADR-06).</p><h3 id="_2-6-seguridad-secretos-y-auditoria" tabindex="-1">2.6 Seguridad, secretos y auditoría <a class="header-anchor" href="#_2-6-seguridad-secretos-y-auditoria" aria-label="Permalink to &quot;2.6 Seguridad, secretos y auditoría&quot;">​</a></h3><h4 id="adr-031-—-auditoria-transaccional-inmutable-con-cadena-de-hash" tabindex="-1">ADR-031 — Auditoría transaccional inmutable con cadena de hash <a class="header-anchor" href="#adr-031-—-auditoria-transaccional-inmutable-con-cadena-de-hash" aria-label="Permalink to &quot;ADR-031 — Auditoría transaccional inmutable con cadena de hash&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada con validación pendiente (PA-NFR-16 asumida)</td></tr><tr><td>Origen</td><td>T02 §7.17; RF-IAM-130 a RF-IAM-138; RNF-NFR-110 a RNF-NFR-119; RN-NFR-020</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop audita de forma selectiva y sin valores previos; las cooperativas necesitan evidencia confiable de cada cambio.</p><p><strong>Decisión.</strong> Registros <code>auditLogs</code>, <code>auditAccess</code>, <code>auditReads</code>, <code>auditMessages</code> y <code>auditAi</code>. Cada cambio persistente se audita en la misma transacción (si falla la auditoría, falla el cambio). La identidad de base del API solo inserta y lee. Encadenamiento de hash por tenant con anclaje diario en almacenamiento WORM fuera de la base. Secretos nunca como valores (se registra &quot;valor cambiado&quot; y huella). Auditoría de lecturas obligatoria para salud, datos bancarios, informes de acceso, exportaciones, soporte y bóveda.</p><p><strong>Alternativas consideradas.</strong> Auditoría selectiva por sentencia (ProCoop): reemplazada (RN-NFR-020). Event sourcing como auditoría: descartado (ARQ-PLA-06).</p><p><strong>Consecuencias.</strong> Volumen alto de <code>auditLogs</code> con archivo en frío (RNF-NFR-116); una restauración no revierte la auditoría (RF-PLA-124).</p><h4 id="adr-032-—-boveda-de-secretos-propia-con-cifrado-por-sobre-y-kms" tabindex="-1">ADR-032 — Bóveda de secretos propia con cifrado por sobre y KMS <a class="header-anchor" href="#adr-032-—-boveda-de-secretos-propia-con-cifrado-por-sobre-y-kms" aria-label="Permalink to &quot;ADR-032 — Bóveda de secretos propia con cifrado por sobre y KMS&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-074, vigente)</td></tr><tr><td>Origen</td><td>DEC-074; PA-INT-02; T06 §5.2 y §7.3; RF-INT-015 a RF-INT-023; RNF-NFR-056, RNF-NFR-068, RNF-NFR-069; RN-DAT-010</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop guarda credenciales en tablas y en código; cada tenant tiene decenas de credenciales de ARCA, pasarelas, bancos, mensajería y red.</p><p><strong>Decisión.</strong> Bóveda única <code>integrationSecrets</code> en MongoDB con cifrado por sobre: AES-256-GCM con clave de datos por tenant, envuelta por una clave maestra en AWS KMS por ambiente, detrás de una interfaz agnóstica. API de solo escritura (solo nombre, huella HMAC y últimos 4 cuando corresponde); rotación con doble versión; cada descifrado auditado (<code>int.secret.decrypted</code>); el worker solo accede al secreto del tenant y conector del job; los demás anexos referencian la bóveda por <code>credentialRef</code>. Nunca se transcriben ni registran valores.</p><p><strong>Alternativas consideradas.</strong> (PA-INT-02) B: HashiCorp Vault autogestionado, más operación. C: clave maestra en variable de entorno, sin separación ni rotación.</p><p><strong>Consecuencias.</strong> Las credenciales heredadas de ProCoop se tratan como comprometidas y se regeneran (RF-INT-023). La continuidad de claves KMS condiciona las restauraciones (RNF-NFR-042).</p><h4 id="adr-033-—-cifrado-de-campos-sensibles-por-tenant-y-categoria" tabindex="-1">ADR-033 — Cifrado de campos sensibles por tenant y categoría <a class="header-anchor" href="#adr-033-—-cifrado-de-campos-sensibles-por-tenant-y-categoria" aria-label="Permalink to &quot;ADR-033 — Cifrado de campos sensibles por tenant y categoría&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-NFR-055 a RNF-NFR-057, RNF-NFR-100; T05 §7.1.12; RN-DAT-009; CTR-NFR-02</td></tr></tbody></table><p><strong>Contexto.</strong> En una base compartida, un error de filtro o un acceso indebido a la base cruda expondría datos de salud o bancarios de todas las cooperativas.</p><p><strong>Decisión.</strong> Cifrado a nivel de aplicación (<code>packages/shared/crypto</code>, única implementación permitida) con AES-256-GCM, nonce de 96 bits y clave de datos por tenant y por categoría; dato autenticado adicional con <code>tenantId</code>, colección, campo e <code>_id</code>. Alcance: salud, electrodependencia, CBU/CVU y cuentas, CUIL y familiares, documentos escaneados, notas confidenciales, secretos y semillas TOTP. Búsqueda exacta por índice ciego HMAC-SHA-256 por tenant. DNI y CUIT no se cifran a nivel de campo (son claves de búsqueda) pero se enmascaran.</p><p><strong>Alternativas consideradas.</strong> Solo cifrado en reposo de volúmenes: insuficiente frente a la base compartida (CTR-NFR-02). Cifrado nativo del motor de base <em>(alternativa de análisis, no registrada en la especificación)</em>.</p><p><strong>Consecuencias.</strong> Sin búsqueda parcial sobre campos cifrados. Rotación de claves de datos con re-cifrado diferido. Las categorías de clave difieren entre T05 y T08 (ver OBS-ADR-02).</p><h4 id="adr-034-—-secretos-de-plataforma-en-gestor-de-secretos-y-arranque-seguro" tabindex="-1">ADR-034 — Secretos de plataforma en gestor de secretos y arranque seguro <a class="header-anchor" href="#adr-034-—-secretos-de-plataforma-en-gestor-de-secretos-y-arranque-seguro" aria-label="Permalink to &quot;ADR-034 — Secretos de plataforma en gestor de secretos y arranque seguro&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-PLA-001, RNF-PLA-005; RNF-NFR-067, RNF-NFR-069, RNF-NFR-070, RNF-NFR-099; RN-NFR-003, RN-NFR-004; RF-INT-083; CTR-NFR-08</td></tr></tbody></table><p><strong>Contexto.</strong> Cadenas de conexión, claves de firma de tokens y credenciales de proveedores de plataforma no pertenecen a un tenant y no pueden vivir en el repositorio ni en archivos <code>.env</code> mantenidos a mano.</p><p><strong>Decisión.</strong> Gestor de secretos por ambiente (AWS Secrets Manager de referencia) con identidad de servicio por componente (API, worker, migraciones, analítica). En producción el proceso no arranca si falta un secreto, si tiene entropía insuficiente, si coincide con un valor de ejemplo o si falta la lista blanca de CORS. Escaneo de secretos en commits, CI e imágenes. Sin contraseñas por defecto ni puertas traseras en ningún ambiente.</p><p><strong>Alternativas consideradas.</strong> <code>.env</code> a mano en servidores (Connectia §2.8): descartado (CTR-NFR-08).</p><p><strong>Consecuencias.</strong> Credenciales productivas inaccesibles desde no producción (RNF-NFR-099); rotación de emergencia en ≤ 4 h.</p><h4 id="adr-035-—-almacenamiento-de-objetos-privado-con-url-firmadas-y-antivirus" tabindex="-1">ADR-035 — Almacenamiento de objetos privado con URL firmadas y antivirus <a class="header-anchor" href="#adr-035-—-almacenamiento-de-objetos-privado-con-url-firmadas-y-antivirus" aria-label="Permalink to &quot;ADR-035 — Almacenamiento de objetos privado con URL firmadas y antivirus&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RF-PLA-012, RF-PLA-025, RF-PLA-027, RF-PLA-120; RNF-NFR-039, RNF-NFR-058, RNF-NFR-078 a RNF-NFR-081; RN-NFR-026; CTR-NFR-07</td></tr></tbody></table><p><strong>Contexto.</strong> Connectia guarda archivos con <code>multer</code> en disco y sirve <code>/uploads</code> públicamente; ProCoop envía PDF al portal por FTP.</p><p><strong>Decisión.</strong> Buckets privados por ambiente con cifrado del lado del servidor por KMS, claves de objeto con prefijo de tenant sin datos personales en el nombre; URL firmadas de un solo objeto emitidas tras verificar tenant, permiso y alcance (descarga ≤ 5 min). Toda subida entra a cuarentena, se valida por firma de contenido, se analiza con antivirus y se reencodifica si es imagen antes de habilitarse. Versionado y bloqueo WORM para comprobantes y documentos firmados.</p><p><strong>Alternativas consideradas.</strong> <code>/uploads</code> público y disco local (Connectia): descartado (CTR-NFR-07). FTP de PDF al portal (ProCoop): descartado (RN-NFR-026).</p><p><strong>Consecuencias.</strong> El producto antivirus de producción queda a definir (ClamAV en el entorno local, <code>02-arquitectura-c4.md</code> §4.2).</p><h3 id="_2-7-integraciones" tabindex="-1">2.7 Integraciones <a class="header-anchor" href="#_2-7-integraciones" aria-label="Permalink to &quot;2.7 Integraciones&quot;">​</a></h3><h4 id="adr-036-—-integraciones-solo-por-conectores-con-estados-explicitos" tabindex="-1">ADR-036 — Integraciones solo por conectores con estados explícitos <a class="header-anchor" href="#adr-036-—-integraciones-solo-por-conectores-con-estados-explicitos" aria-label="Permalink to &quot;ADR-036 — Integraciones solo por conectores con estados explícitos&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>Maestra §5.3 ARQ-06; T06 §5.1 y §5.5; RF-INT-001 a RF-INT-014, RF-INT-032 a RF-INT-046; RF-PLA-142; RNF-NFR-047, RNF-NFR-221, RNF-NFR-222, RNF-NFR-227; RN-INT-012, RN-INT-035</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop integra con decenas de terceros mediante procesos por cooperativa, credenciales estáticas, esperas fijas y reintentos ad hoc.</p><p><strong>Decisión.</strong> Toda integración pasa por un conector del marco T06 con catálogo de proveedores, conexión por tenant, capacidades declaradas, modo prueba/producción, credenciales en bóveda y colas por categoría. Cada llamada originada por un cambio de negocio se registra como <code>integrationOperation</code> en la misma transacción. Estados Pendiente, Confirmado, Fallido y Resultado incierto; ante incertidumbre se ejecuta la consulta de reconciliación antes de reintentar. Circuit breaker por conexión, límite de tasa saliente, taxonomía de errores, bandeja de operaciones detenidas y bitácora saneada. El conector no escribe colecciones de otros módulos; los efectos llegan por eventos.</p><p><strong>Alternativas consideradas.</strong> Un proceso por cooperativa con credenciales estáticas (ProCoop, RN-INT-012): reemplazado. Reintentos de persistencia en bucle (RN-INT-035): reemplazados por transacción + outbox.</p><p><strong>Consecuencias.</strong> Nuevo proveedor = nuevo adaptador sin tocar el dominio. Requiere simulador por conector para pruebas (RF-INT-031).</p><h4 id="adr-037-—-webhooks-entrantes-como-disparadores-verificados" tabindex="-1">ADR-037 — Webhooks entrantes como disparadores verificados <a class="header-anchor" href="#adr-037-—-webhooks-entrantes-como-disparadores-verificados" aria-label="Permalink to &quot;ADR-037 — Webhooks entrantes como disparadores verificados&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RF-INT-053 a RF-INT-058; RF-PLA-031; RNF-NFR-018, RNF-NFR-088; RN-NFR-008; RN-INT-009, RN-INT-032</td></tr></tbody></table><p><strong>Contexto.</strong> En ProCoop una pasarela acepta como pagado el importe que informa el portal y los avisos llegan por Firebase escuchado por un agente.</p><p><strong>Decisión.</strong> Endpoint por conexión en <code>/api/public/{tenantSlug}/webhooks/{endpointKey}</code> con clave aleatoria rotable; verificación de firma del proveedor (HMAC, firma asimétrica, mTLS o lista de IP) con ventana anti-repetición; bandeja durable, acuse 2xx en &lt; 2 s y procesamiento asíncrono con deduplicación. El webhook es solo disparador: antes de un efecto económico se reconsulta el estado al proveedor con credenciales propias. El retorno del navegador nunca confirma un pago.</p><p><strong>Alternativas consideradas.</strong> Confirmación por importe informado por el cliente o el portal: descartada (RN-INT-009, RN-NFR-008). Escucha de Firebase por agente: reemplazada (RN-INT-032).</p><p><strong>Consecuencias.</strong> Un webhook falso con firma válida no confirma pagos inexistentes. Dependencia de la API de consulta de cada proveedor.</p><h4 id="adr-038-—-egreso-controlado-y-proteccion-contra-ssrf" tabindex="-1">ADR-038 — Egreso controlado y protección contra SSRF <a class="header-anchor" href="#adr-038-—-egreso-controlado-y-proteccion-contra-ssrf" aria-label="Permalink to &quot;ADR-038 — Egreso controlado y protección contra SSRF&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RF-INT-079, RF-INT-080; RNF-NFR-053, RNF-NFR-087; RNF-PLA-003</td></tr></tbody></table><p><strong>Contexto.</strong> Connectia expone un proxy genérico de medios (riesgo SSRF) y ProCoop permite desactivar la validación de certificados con una variable.</p><p><strong>Decisión.</strong> Toda llamada saliente usa un cliente HTTP único (<code>packages/shared/http</code>) con lista blanca de hosts por conector y ambiente, bloqueo de rangos privados, loopback y servicio de metadatos de la nube. TLS 1.2+ con validación de certificado siempre activa, sin opción para desactivarla. Egreso de los workers por NAT o proxy con lista blanca.</p><p><strong>Alternativas consideradas.</strong> Proxy genérico de medios (Connectia V-05): descartado. Parámetro para desactivar la validación TLS (ProCoop): descartado (RF-INT-080).</p><p><strong>Consecuencias.</strong> Los tipos de conector &quot;genéricos&quot; con URL configurable por el tenant requieren validación adicional de destino.</p><h4 id="adr-039-—-emision-fiscal-con-contingencia-y-numeracion-sin-huecos" tabindex="-1">ADR-039 — Emisión fiscal con contingencia y numeración sin huecos <a class="header-anchor" href="#adr-039-—-emision-fiscal-con-contingencia-y-numeracion-sin-huecos" aria-label="Permalink to &quot;ADR-039 — Emisión fiscal con contingencia y numeración sin huecos&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-018, DEC-035 y DEC-038, vigentes)</td></tr><tr><td>Origen</td><td>DEC-018, DEC-035, DEC-038; PA-CFG-P2-06; RF-INT-038, RF-INT-074, RF-INT-076; RN-INT-005; RNF-NFR-011, RNF-NFR-217</td></tr></tbody></table><p><strong>Contexto.</strong> ARCA puede estar lenta o caída en una facturación masiva o en mostrador; un timeout en la solicitud de CAE puede generar números duplicados.</p><p><strong>Decisión.</strong> En mostrador se espera el CAE con tiempo máximo; luego CAEA (si está habilitado) o comprobante pendiente no entregable como fiscal. En masiva se emite y encola, pausando solo la autorización. El número fiscal se asigna al emitir, en orden del lote, dentro de la transacción; si ARCA rechaza se reenvía el mismo número; antes de reintentar se consulta el último autorizado. El cierre de contingencia exige conciliación completa.</p><p><strong>Alternativas consideradas.</strong> (PA-CFG-P2-06) B: entregar siempre y autorizar en diferido, con comprobantes sin CAE. C: bloquear la venta hasta que ARCA responda.</p><p><strong>Consecuencias.</strong> Estados &quot;incierto&quot; y circuit breaker por conexión fiscal; tablero de comprobantes pendientes de CAE.</p><h4 id="adr-040-—-certificado-arca-generado-en-la-plataforma" tabindex="-1">ADR-040 — Certificado ARCA generado en la plataforma <a class="header-anchor" href="#adr-040-—-certificado-arca-generado-en-la-plataforma" aria-label="Permalink to &quot;ADR-040 — Certificado ARCA generado en la plataforma&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-053, vigente)</td></tr><tr><td>Origen</td><td>DEC-053; PA-FIS-03; RF-INT-024 a RF-INT-027; RN-INT-020; RNF-NFR-071</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop guarda el PFX del certificado ARCA sin contraseña en una carpeta.</p><p><strong>Decisión.</strong> La plataforma genera el par de claves (RSA 2048 o superior) y el CSR con los datos del tenant; la clave privada nunca sale de la bóveda. Se admite importar un PFX existente. Varios certificados por conexión para renovar sin corte; alertas de vencimiento escalonadas; certificado vencido o rechazado bloquea la conexión y pausa la cola.</p><p><strong>Alternativas consideradas.</strong> (PA-FIS-03) B: solo carga de PFX, con la clave pasando por equipos del usuario. C: solo generación en plataforma, que obliga a renovar certificados vigentes.</p><p><strong>Consecuencias.</strong> La importación de PFX es el camino de menor seguridad y debe auditarse y rotarse en la primera renovación.</p><h4 id="adr-041-—-credenciales-de-proveedor-de-plataforma-o-propias-del-tenant" tabindex="-1">ADR-041 — Credenciales de proveedor de plataforma o propias del tenant <a class="header-anchor" href="#adr-041-—-credenciales-de-proveedor-de-plataforma-o-propias-del-tenant" aria-label="Permalink to &quot;ADR-041 — Credenciales de proveedor de plataforma o propias del tenant&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-020 y DEC-077, vigentes)</td></tr><tr><td>Origen</td><td>DEC-020 (PA-CFG-P1-03); DEC-077 (PA-COM-04); DEC-065; RF-INT-012, RF-INT-013; RF-PLA-029; RNF-NFR-250, RNF-NFR-251</td></tr></tbody></table><p><strong>Contexto.</strong> Mapas, IA y mensajería pueden contratarse por la plataforma y revenderse, o por cada cooperativa.</p><p><strong>Decisión.</strong> La plataforma provee claves de mapas e IA, con opción de clave propia del tenant en la bóveda. La mensajería admite conector propio del tenant o proveedor de plataforma revendido con consumo medido como complemento del pack. El consumo se atribuye por tenant y tiene tope mensual.</p><p><strong>Alternativas consideradas.</strong> (PA-CFG-P1-03) B: cada tenant carga su clave. C: solo plataforma. (PA-COM-04) B: solo proveedor de plataforma. C: solo conector propio.</p><p><strong>Consecuencias.</strong> Las conexiones de <code>PLATFORM</code> compartidas deben aislar contexto y caché por tenant (RF-PLA-029); al alcanzar el tope la IA se degrada a &quot;sin IA&quot;.</p><h4 id="adr-042-—-proveedores-iniciales-detras-de-adaptadores-canonicos" tabindex="-1">ADR-042 — Proveedores iniciales detrás de adaptadores canónicos <a class="header-anchor" href="#adr-042-—-proveedores-iniciales-detras-de-adaptadores-canonicos" aria-label="Permalink to &quot;ADR-042 — Proveedores iniciales detrás de adaptadores canónicos&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-015, DEC-046 y DEC-055, vigentes; PA-INT-06 asumida)</td></tr><tr><td>Origen</td><td>DEC-015 (PA-CFG-P3-05); DEC-046 (PA-PER-13); DEC-055 (PA-CRM-06); PA-INT-06; DT-05 y DT-06 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> Hay muchos proveedores posibles por categoría y el piloto necesita un conjunto acotado.</p><p><strong>Decisión.</strong> Pasarelas Pagos360, Mercado Pago, SIRO y Red Link en O5 y el resto como extensión en O11; Georef para normalizar y geocodificar y Google Maps para mapa y autocompletado; WhatsApp con Meta Cloud API por defecto y adaptador para Trii; SMS con agregador local de plataforma e interfaz para otros. Todos detrás de contratos canónicos de T06.</p><p><strong>Alternativas consideradas.</strong> (PA-CFG-P3-05) B: todas las pasarelas en O5. C: solo las de cada tenant migrado. (PA-CRM-06) B: solo Trii. C: solo Meta Cloud API.</p><p><strong>Consecuencias.</strong> Cada proveedor es subencargado o tercero con ficha de datos intercambiados (RF-INT-082). Quedan inconsistencias menores de T01 §7.1 (Leaflet, Twilio) registradas como DT-05 y DT-06.</p><h4 id="adr-043-—-aprovisionamiento-automatico-asincrono-con-respaldo-manual" tabindex="-1">ADR-043 — Aprovisionamiento automático asíncrono con respaldo manual <a class="header-anchor" href="#adr-043-—-aprovisionamiento-automatico-asincrono-con-respaldo-manual" aria-label="Permalink to &quot;ADR-043 — Aprovisionamiento automático asíncrono con respaldo manual&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-041 y DEC-042, vigentes)</td></tr><tr><td>Origen</td><td>DEC-041 (PA-TEC-09); DEC-042; DEC-014; RN-INT-040, RN-INT-065</td></tr></tbody></table><p><strong>Contexto.</strong> El alta, el corte y la reconexión de Internet deben reflejarse en la red (MikroTik, RADIUS, SmartOLT) sin intervención manual sistemática.</p><p><strong>Decisión.</strong> Aprovisionamiento automático y asíncrono vía conector con respaldo manual al agotar reintentos; MikroTik, RADIUS y SmartOLT en O3. Un intento de corte o reconexión no se repite sin verificar su estado.</p><p><strong>Alternativas consideradas.</strong> (PA-TEC-09) B: solo manual con tarea para el NOC. C: automático sin respaldo manual.</p><p><strong>Consecuencias.</strong> Credenciales de equipos de red en bóveda; comandos remotos solo por operaciones declaradas del conector.</p><h3 id="_2-8-inteligencia-artificial-documentos-y-canales" tabindex="-1">2.8 Inteligencia artificial, documentos y canales <a class="header-anchor" href="#_2-8-inteligencia-artificial-documentos-y-canales" aria-label="Permalink to &quot;2.8 Inteligencia artificial, documentos y canales&quot;">​</a></h3><h4 id="adr-044-—-la-inteligencia-artificial-solo-propone" tabindex="-1">ADR-044 — La inteligencia artificial solo propone <a class="header-anchor" href="#adr-044-—-la-inteligencia-artificial-solo-propone" aria-label="Permalink to &quot;ADR-044 — La inteligencia artificial solo propone&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (ARQ-08; DEC-056 vigente)</td></tr><tr><td>Origen</td><td>Maestra §5.3 ARQ-08; DEC-056; DEC-008; PA-INT-08; PA-NFR-09; RN-NFR-010 a RN-NFR-012; RF-IAM-150 a RF-IAM-153; RF-INT-086; RF-PLA-029; RNF-NFR-098; CTR-NFR-18</td></tr></tbody></table><p><strong>Contexto.</strong> La IA se usa en alta de tenants, moderación del muro, atención y BI; Connectia la invoca por HTTP directo y ProCoop tiene una clave de proveedor en código.</p><p><strong>Decisión.</strong> La IA solo propone; toda acción con efecto requiere confirmación humana y auditoría. Actúa con los permisos del usuario que la invoca. Proveedor como conector multiproveedor con registro de uso; datos personales minimizados y redactados, nunca datos de salud; contenido de mensajes y adjuntos tratado como datos, no instrucciones; salidas validadas por esquema; funciones habilitables por tenant y apagadas hasta su aceptación.</p><p><strong>Alternativas consideradas.</strong> IA por HTTP directo con proveedor automático (Connectia §2.1): reemplazada (CTR-NFR-18).</p><p><strong>Consecuencias.</strong> Batería adversarial de inyección de instrucciones en CI (RA-12); <code>auditAi</code> por cada uso.</p><h4 id="adr-045-—-motor-de-pdf-con-chromium-sin-interfaz-en-workers-dedicados" tabindex="-1">ADR-045 — Motor de PDF con Chromium sin interfaz en workers dedicados <a class="header-anchor" href="#adr-045-—-motor-de-pdf-con-chromium-sin-interfaz-en-workers-dedicados" aria-label="Permalink to &quot;ADR-045 — Motor de PDF con Chromium sin interfaz en workers dedicados&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-080, vigente)</td></tr><tr><td>Origen</td><td>DEC-080; PA-WFL-05; RNF-NFR-012, RNF-NFR-199, RNF-NFR-230; DT-10 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> Se necesitan PDF/A con fuentes embebidas, código de barras y QR fiscal, plantillas editables por el tenant y lotes de 50.000 documentos en ≤ 60 min.</p><p><strong>Decisión.</strong> HTML + CSS renderizado con Chromium sin interfaz en workers dedicados, con validación PDF/A posterior; hash SHA-256 de cada documento emitido.</p><p><strong>Alternativas consideradas.</strong> (PA-WFL-05) B: biblioteca de composición programática, más rápida y sin plantilla editable. C: servicio externo de render, con costo por documento y datos personales fuera. Interop con Office (ProCoop, RN-INT-059): descartada.</p><p><strong>Consecuencias.</strong> Imagen, cola y dimensionamiento de los workers de PDF no están declarados en T01 (DT-10). El aislamiento del navegador sin interfaz no está especificado (ver <code>28-modelo-amenazas-seguridad.md</code>).</p><h4 id="adr-046-—-interfaz-de-firma-propia-con-otp-y-firma-digital-licenciada" tabindex="-1">ADR-046 — Interfaz de firma propia con OTP y firma digital licenciada <a class="header-anchor" href="#adr-046-—-interfaz-de-firma-propia-con-otp-y-firma-digital-licenciada" aria-label="Permalink to &quot;ADR-046 — Interfaz de firma propia con OTP y firma digital licenciada&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-078, vigente; proveedor a elegir antes de O3)</td></tr><tr><td>Origen</td><td>DEC-078; PA-INT-22; PA-WFL-06; RNF-NFR-230</td></tr></tbody></table><p><strong>Contexto.</strong> Conformidades de instalación, convenios y trámites requieren firma del socio; recibos de sueldo y actas requieren firma digital.</p><p><strong>Decisión.</strong> Interfaz de firma propia; firma electrónica con OTP por defecto; firma digital con proveedor licenciado solo para recibos de sueldo y actas (O8/O9). El proveedor se elige antes de O3.</p><p><strong>Alternativas consideradas.</strong> (PA-WFL-06) B: firma digital en todo desde O1. C: solo firma electrónica interna sin proveedor.</p><p><strong>Consecuencias.</strong> El proveedor de firma digital es un subencargado aún no definido (RA-08).</p><h4 id="adr-047-—-pwa-unica-con-cola-offline-idempotente" tabindex="-1">ADR-047 — PWA única con cola offline idempotente <a class="header-anchor" href="#adr-047-—-pwa-unica-con-cola-offline-idempotente" aria-label="Permalink to &quot;ADR-047 — PWA única con cola offline idempotente&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada con validación pendiente (PA-NFR-14 asumida)</td></tr><tr><td>Origen</td><td>Maestra §8; RF-PLA-150; RNF-NFR-017, RNF-NFR-186 a RNF-NFR-191, RNF-NFR-219; PA-NFR-14; CTR-NFR-10</td></tr></tbody></table><p><strong>Contexto.</strong> Técnicos, lecturistas y cobradores trabajan sin conexión hasta 7 días; Connectia usa colas por dominio en <code>localStorage</code>.</p><p><strong>Decisión.</strong> Una sola PWA con experiencia por rol (socio, empleado, campo) y un motor único de cola offline en IndexedDB con <code>clientMutationId</code> (UUIDv7) por mutación y envío por lotes idempotente. Solo se descargan los datos de tareas asignadas con vencimiento ≤ 7 días; borrado al cerrar o revocar sesión; evidencias sensibles cifradas con clave WebCrypto no exportable; sin tokens de larga duración en IndexedDB. Login, cobros, anulaciones y configuración nunca se encolan offline. <code>/api</code> con estrategia NetworkOnly.</p><p><strong>Alternativas consideradas.</strong> Colas por dominio en <code>localStorage</code> (Connectia §3.7): reemplazadas (CTR-NFR-10).</p><p><strong>Consecuencias.</strong> Conflictos de sincronización derivados a una bandeja; actualización automática sin perder la cola.</p><h4 id="adr-048-—-agente-local-propio-con-canal-saliente" tabindex="-1">ADR-048 — Agente local propio con canal saliente <a class="header-anchor" href="#adr-048-—-agente-local-propio-con-canal-saliente" aria-label="Permalink to &quot;ADR-048 — Agente local propio con canal saliente&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (asumida, DEC-072)</td></tr><tr><td>Origen</td><td>PA-INT-09; DEC-007; RF-INT-084; RF-IAM-049; RNF-NFR-258; T06 §7.15; RN-INT-058</td></tr></tbody></table><p><strong>Contexto.</strong> Impresoras térmicas y fiscales, turnero, balanzas, lectores y colectores requieren software en el puesto. ProCoop usa un agente vigilado por otro proceso que se autoactualiza desde un bucket del proveedor.</p><p><strong>Decisión.</strong> Agente propio GoodApps (O10), multiplataforma, emparejado por código de un solo uso, con identidad de dispositivo, canal saliente WebSocket TLS sin puertos entrantes, comandos firmados con expiración de una lista declarada, cola local cifrada, latido cada 60 s y actualizaciones firmadas y verificadas. Nunca almacena datos de tarjeta ni credenciales de base.</p><p><strong>Alternativas consideradas.</strong> (PA-INT-09) B: solo impresión desde el navegador, sin turnero ni periféricos. C: software de terceros por dispositivo, heterogéneo. Autoactualización desde bucket del proveedor (ProCoop): descartada (RN-INT-058).</p><p><strong>Consecuencias.</strong> Requiere emisión y revocación de credenciales por dispositivo; la tecnología de implementación del agente está a definir.</p><h3 id="_2-9-privacidad-operacion-y-entrega" tabindex="-1">2.9 Privacidad, operación y entrega <a class="header-anchor" href="#_2-9-privacidad-operacion-y-entrega" aria-label="Permalink to &quot;2.9 Privacidad, operación y entrega&quot;">​</a></h3><h4 id="adr-049-—-encargado-de-tratamiento-exportacion-purga-y-libro-de-supresiones" tabindex="-1">ADR-049 — Encargado de tratamiento: exportación, purga y libro de supresiones <a class="header-anchor" href="#adr-049-—-encargado-de-tratamiento-exportacion-purga-y-libro-de-supresiones" aria-label="Permalink to &quot;ADR-049 — Encargado de tratamiento: exportación, purga y libro de supresiones&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-076, vigente)</td></tr><tr><td>Origen</td><td>DEC-076; PA-NFR-07; RNF-NFR-045, RNF-NFR-107, RNF-NFR-108; RF-PLA-156 a RF-PLA-160; RF-NFR-006 a RF-NFR-013; T05 §7.1.1 y §7.1.13</td></tr></tbody></table><p><strong>Contexto.</strong> La cooperativa es responsable de los datos de sus socios; la plataforma los trata por su cuenta y debe poder devolverlos o destruirlos.</p><p><strong>Decisión.</strong> GoodApps actúa como prestador de servicios de tratamiento (art. 25 Ley 25.326): contrato tipo de encargo, registro público de subencargados, exportación completa del tenant en formatos abiertos y destrucción en ≤ 30 días desde la aceptación de la exportación (o conservación cifrada hasta 2 años si la cooperativa lo autoriza), con constancia. Las supresiones se registran en <code>erasureLedger</code>, en una base separada excluida de las restauraciones, y se reaplican antes de habilitar el acceso tras restaurar.</p><p><strong>Alternativas consideradas.</strong> (PA-NFR-07) B: corresponsable del tratamiento. C: definir caso por caso.</p><p><strong>Consecuencias.</strong> La plataforma no decide finalidades; los derechos de los titulares se gestionan en nombre del tenant (bandeja de solicitudes, informe de acceso).</p><h4 id="adr-050-—-observabilidad-con-opentelemetry-y-correlacion-extremo-a-extremo" tabindex="-1">ADR-050 — Observabilidad con OpenTelemetry y correlación extremo a extremo <a class="header-anchor" href="#adr-050-—-observabilidad-con-opentelemetry-y-correlacion-extremo-a-extremo" aria-label="Permalink to &quot;ADR-050 — Observabilidad con OpenTelemetry y correlación extremo a extremo&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (backend de observabilidad a definir)</td></tr><tr><td>Origen</td><td>RNF-NFR-119 a RNF-NFR-139; RF-PLA-136 a RF-PLA-145; RN-NFR-021; CTR-NFR-14</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop envía excepciones por correo y guarda logs en archivos locales; en SaaS hay que seguir una operación desde el clic hasta ARCA sin exponer datos personales.</p><p><strong>Decisión.</strong> Logs JSON en una línea (pino) con <code>tenantId</code>, <code>requestId</code>, <code>traceId</code>, redacción automática de secretos y datos personales; métricas RED/USE con control de cardinalidad; trazas OpenTelemetry con W3C Trace Context desde el front hasta outbox, jobs y conectores; alertas por presupuesto de error y de seguridad; proveedores de observabilidad como subencargados que solo reciben datos redactados.</p><p><strong>Alternativas consideradas.</strong> Envío de excepciones por correo (ProCoop): descartado (CTR-NFR-14, RN-NFR-021).</p><p><strong>Consecuencias.</strong> El backend (Prometheus/Grafana o CloudWatch) queda a definir; endpoints de salud con convención aún no unificada (DT-02).</p><h4 id="adr-051-—-entrega-continua-con-imagenes-firmadas-y-migraciones-expandir-contraer" tabindex="-1">ADR-051 — Entrega continua con imágenes firmadas y migraciones expandir/contraer <a class="header-anchor" href="#adr-051-—-entrega-continua-con-imagenes-firmadas-y-migraciones-expandir-contraer" aria-label="Permalink to &quot;ADR-051 — Entrega continua con imágenes firmadas y migraciones expandir/contraer&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada</td></tr><tr><td>Origen</td><td>RNF-NFR-164 a RNF-NFR-169, RNF-NFR-236; RF-PLA-146 a RF-PLA-149; RN-NFR-022, RN-NFR-023; T01 §7.10</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop se actualiza descargando binarios y ejecuta chequeos de estructura al primer login.</p><p><strong>Decisión.</strong> Pipeline por PR con lint, chequeos de estructura, fronteras e índices, pruebas unitarias e integración con Mongo y Redis reales, aislamiento, permisos negativos, contrato, SAST, SCA, secretos, SBOM y escaneo de imágenes. Imágenes firmadas y verificadas por política de admisión; despliegue rolling o blue-green por anillos con rollback ≤ 15 min; migraciones versionadas e idempotentes como paso del despliegue con patrón expandir/contraer; feature flags por tenant. Plataforma de CI de referencia: GitHub Actions.</p><p><strong>Alternativas consideradas.</strong> Descarga de binarios en tiempo de ejecución (ProCoop <code>Version.gzip</code>): descartada (RN-NFR-023). Migraciones al primer login: descartadas (RN-NFR-022).</p><p><strong>Consecuencias.</strong> Congelamiento de despliegues en días críticos del tenant (RNF-NFR-034); dos revisiones obligatorias en código de tenancy, autorización, bóveda, pagos, fiscal e IaC (RNF-NFR-166).</p><h4 id="adr-052-—-ambientes-separados-y-datos-ficticios-fuera-de-produccion" tabindex="-1">ADR-052 — Ambientes separados y datos ficticios fuera de producción <a class="header-anchor" href="#adr-052-—-ambientes-separados-y-datos-ficticios-fuera-de-produccion" aria-label="Permalink to &quot;ADR-052 — Ambientes separados y datos ficticios fuera de producción&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (PA-PLA-07 asumida)</td></tr><tr><td>Origen</td><td>RF-PLA-109, RF-PLA-110; RN-NFR-014, RN-NFR-015; RNF-NFR-099, RNF-NFR-160, RNF-NFR-161, RNF-NFR-170; RF-INT-030; PA-PLA-07; DT-03 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop y Connectia tienen usuarios demo con clave conocida y bases DEMO; los ensayos con datos reales exponen a los socios.</p><p><strong>Decisión.</strong> Siete ambientes (<code>local</code>, <code>ci</code>, <code>dev</code>, <code>staging</code>, <code>sandbox</code>, <code>demo</code>, <code>prod</code>) con datos, secretos, dominios y credenciales propios; cuentas de nube separadas para producción sin rutas de red con no producción. Datos de no producción ficticios (juego canónico TEN-001 y TEN-002); la precarga de demostración se niega a ejecutar en producción; desde no producción no se emiten comprobantes reales, no se cobra ni se envían mensajes reales.</p><p><strong>Alternativas consideradas.</strong> (PA-PLA-07) Copia anonimizada en sandbox solo con aprobación del administrador y de seguridad, como excepción.</p><p><strong>Consecuencias.</strong> El tratamiento de copias reales para ensayos de migración requiere precisión (ver OBS-ADR-07).</p><h3 id="_2-10-migracion-y-transicion" tabindex="-1">2.10 Migración y transición <a class="header-anchor" href="#_2-10-migracion-y-transicion" aria-label="Permalink to &quot;2.10 Migración y transición&quot;">​</a></h3><h4 id="adr-053-—-migracion-con-extraccion-de-solo-lectura-snapshots-e-historico-acotado" tabindex="-1">ADR-053 — Migración con extracción de solo lectura, snapshots e histórico acotado <a class="header-anchor" href="#adr-053-—-migracion-con-extraccion-de-solo-lectura-snapshots-e-historico-acotado" aria-label="Permalink to &quot;ADR-053 — Migración con extracción de solo lectura, snapshots e histórico acotado&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-070 y DEC-087, vigentes)</td></tr><tr><td>Origen</td><td>DEC-070 (PA-MIG-01); DEC-087 (PA-DAT-02); RF-MIG-010, RF-MIG-011, RF-MIG-060, RF-MIG-062, RF-MIG-090, RF-MIG-095 a RF-MIG-097; RN-MIG-013; PA-MIG-07; T05 §7.1.11</td></tr></tbody></table><p><strong>Contexto.</strong> ProCoop tiene 659 tablas, adjuntos y una base del portal; la migración debe ser repetible, trazable y no alterar el origen.</p><p><strong>Decisión.</strong> Extracción con usuario de solo lectura, sin bloqueos, como snapshot inmutable cifrado en almacenamiento privado con manifiesto y hash. Ejercicio en curso + 24 meses en estructuras tipadas; el resto en <code>legacyRecords</code>; copia del origen conservada 10 años con acceso restringido y auditado. Subdocumento <code>legacy</code> en todo documento migrado. Detalle histórico de más de 36 meses archivado con consulta diferida; facturas, recibos y asientos siempre en línea. Credenciales y contraseñas nunca se migran; los usuarios reciben invitación de activación. Perfiles de anonimización para ensayos.</p><p><strong>Alternativas consideradas.</strong> (PA-MIG-01) B: todo tipado. C: solo saldos vivos y archivo. (PA-DAT-02) B: todo en línea 10 años. C: en línea 24 meses.</p><p><strong>Consecuencias.</strong> Doble modelo de consulta (tipado y <code>legacyRecords</code>); custodia de un snapshot con datos personales durante 10 años.</p><h4 id="adr-054-—-convivencia-con-procoop-y-corte-por-etapas" tabindex="-1">ADR-054 — Convivencia con ProCoop y corte por etapas <a class="header-anchor" href="#adr-054-—-convivencia-con-procoop-y-corte-por-etapas" aria-label="Permalink to &quot;ADR-054 — Convivencia con ProCoop y corte por etapas&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-068, DEC-069, DEC-088 y DEC-089, vigentes)</td></tr><tr><td>Origen</td><td>DEC-068 (PA-MIG-04); DEC-069; DEC-088; DEC-089; RA-10 de <code>02-arquitectura-c4.md</code></td></tr></tbody></table><p><strong>Contexto.</strong> La cooperativa piloto Laguna Larga (<code>LAG</code>) opera electricidad (con prepago) y gas por redes; un corte único concentra el riesgo.</p><p><strong>Decisión.</strong> Corte comercial (M01 a M09) primero, por servicio: electricidad, gas por redes y prepago de LAG después del cierre de O7, cuando el paralelo apruebe los ciclos consecutivos; contabilidad, compras, stock, tesorería y sueldos siguen en ProCoop hasta el corte administrativo en O11. Durante la convivencia GoodApps contabiliza en un plan marcado no oficial y concilia contra ProCoop. De <code>PR_LAG_DEMO</code> solo se toma configuración, nunca datos personales.</p><p><strong>Alternativas consideradas.</strong> (PA-MIG-04) B: corte único total. C: corte por servicio con convivencia larga (adoptada parcialmente por DEC-089 para el corte comercial).</p><p><strong>Consecuencias.</strong> Doble fuente de verdad contable temporal (RA-10); interfaces de intercambio con ProCoop durante la convivencia.</p><h4 id="adr-055-—-identificador-de-pago-autocontenido-durante-la-transicion" tabindex="-1">ADR-055 — Identificador de pago autocontenido durante la transición <a class="header-anchor" href="#adr-055-—-identificador-de-pago-autocontenido-durante-la-transicion" aria-label="Permalink to &quot;ADR-055 — Identificador de pago autocontenido durante la transición&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Estado</td><td>Aceptada (DEC-050, vigente)</td></tr><tr><td>Origen</td><td>DEC-050 (PA-COB-09); T07; M07</td></tr></tbody></table><p><strong>Contexto.</strong> Al migrar, circulan facturas de ProCoop con códigos de pago publicados en redes de cobranza.</p><p><strong>Decisión.</strong> GoodApps usa un identificador de pago nuevo y autocontenido y resuelve además la clave ProCoop hasta que vencen sus facturas.</p><p><strong>Alternativas consideradas.</strong> Las opciones de PA-COB-09 no están detalladas en las fuentes leídas <em>(se recomienda completarlas al pasar este ADR al repositorio)</em>.</p><p><strong>Consecuencias.</strong> Tabla de alias de claves heredadas (<code>legacyKeyAliases</code>) con vencimiento; imputación con doble resolución durante el período de transición.</p><hr><h2 id="_3-decisiones-no-incluidas-como-adr" tabindex="-1">3. Decisiones no incluidas como ADR <a class="header-anchor" href="#_3-decisiones-no-incluidas-como-adr" aria-label="Permalink to &quot;3. Decisiones no incluidas como ADR&quot;">​</a></h2><p>Las siguientes DEC son reglas de negocio u organización del entregable y no constituyen decisiones de arquitectura; su efecto técnico, cuando existe, queda cubierto por los ADR citados.</p><table tabindex="0"><thead><tr><th>DEC</th><th>Tema</th><th>Motivo de exclusión</th></tr></thead><tbody><tr><td>DEC-005, DEC-006, DEC-007, DEC-010</td><td>Piloto Internet, olas sin fechas, alcance total, formato del entregable</td><td>Planificación y alcance. DEC-007 se refleja en ADR-048.</td></tr><tr><td>DEC-008, DEC-009</td><td>Muro editorial; contabilidad temprana</td><td>Producto y planificación funcional. La moderación con IA se rige por ADR-044.</td></tr><tr><td>DEC-011 a DEC-014, DEC-016, DEC-017, DEC-019, DEC-021 a DEC-024, DEC-027 a DEC-034, DEC-036, DEC-037, DEC-039, DEC-040, DEC-043 a DEC-045, DEC-048, DEC-049, DEC-051, DEC-052, DEC-054, DEC-057 a DEC-061, DEC-071, DEC-082 a DEC-086</td><td>Reglas de catálogo, facturación, cobranza, mora, técnica, personas, fiscal, institucional y servicios</td><td>Reglas de negocio funcionales. DEC-014 y DEC-043 se citan en ADR-043 y ADR-027.</td></tr><tr><td>DEC-047, DEC-072, DEC-073</td><td>Política de preguntas; asunción de recomendadas; fichas verticales</td><td>Gobierno de la especificación. DEC-072 define el estado &quot;asumida&quot;.</td></tr><tr><td>DEC-065</td><td>Modelo comercial del SaaS</td><td>Comercial; su efecto técnico (tenant <code>PLATFORM</code> y cupos) está en ADR-011 y ADR-041.</td></tr><tr><td>DEC-081</td><td>Cooperativa piloto no definida</td><td>Reemplazada por DEC-088 (ADR-054).</td></tr></tbody></table><hr><h2 id="_4-observaciones-e-inconsistencias-detectadas" tabindex="-1">4. Observaciones e inconsistencias detectadas <a class="header-anchor" href="#_4-observaciones-e-inconsistencias-detectadas" aria-label="Permalink to &quot;4. Observaciones e inconsistencias detectadas&quot;">​</a></h2><p>Diferencias encontradas al elaborar este registro. No se corrige la especificación; se registran para su resolución por el responsable de cada anexo. Las inconsistencias DT-01 a DT-10 de <code>02-arquitectura-c4.md</code> §11.2 siguen vigentes y no se repiten.</p><table tabindex="0"><thead><tr><th>ID</th><th>Tema</th><th>Observación</th><th>ADR afectado</th></tr></thead><tbody><tr><td>OBS-ADR-01</td><td>Ubicación de los ADR</td><td>RNF-NFR-243 exige un ADR por archivo en <code>docs/adr/NNNN-titulo.md</code> para <strong>cada</strong> DEC (incluidas DEC-001 a DEC-010) y cada CTR técnica. Este registro filtra las DEC no técnicas (sección 3) y es un documento derivado; la especificación no aclara si las DEC de negocio también requieren ADR.</td><td>Todos</td></tr><tr><td>OBS-ADR-02</td><td>Categorías de clave de datos</td><td>T08 RNF-NFR-056 y <code>02-arquitectura-c4.md</code> §8.4 definen claves de datos por categoría <code>salud</code>, <code>financiero</code> y <code>secreto</code>; T05 §7.1.12 usa <code>dek-salud</code>, <code>dek-laboral</code>, <code>dek-judicial</code> y <code>dek-financiero</code> y deja los secretos solo en la bóveda.</td><td>ADR-033</td></tr><tr><td>OBS-ADR-03</td><td>Lista blanca de colecciones globales</td><td>RF-PLA-023 (T01) lista <code>tenants</code>, <code>moduleCatalog</code>, <code>platformPlans</code>, <code>releases</code>, <code>featureFlags</code>, <code>backupPolicies</code>, <code>alertRules</code> y <code>schemaMigrations</code>; T05 §7.1.3 agrega <code>identities</code>, <code>federatedLinks</code>, <code>outboxEvents</code> y <code>jobRuns</code> del despachador y <code>erasureLedger</code>, y no menciona <code>platformPlans</code>, <code>releases</code>, <code>featureFlags</code>, <code>backupPolicies</code> ni <code>alertRules</code>.</td><td>ADR-011, ADR-025</td></tr><tr><td>OBS-ADR-04</td><td>Transacciones entre módulos</td><td>ARQ-PLA-03 (T01) permite comandos síncronos de otro módulo &quot;en la misma transacción si el llamador pasa <code>session</code>&quot;; T05 §7.1.15 dice que &quot;las transacciones no cruzan módulos&quot; y que la coordinación es por eventos o por <code>operations</code> de T11.</td><td>ADR-002, ADR-019</td></tr><tr><td>OBS-ADR-05</td><td>Colecciones técnicas duplicadas</td><td>CTR-NFR-22 registra que T08 §15.1 define <code>idempotencyKeys</code>, <code>processedEvents</code>, <code>auditEvents</code> y otras colecciones que T01 y T02 definen con otro nombre (<code>inboxReceipts</code>, <code>auditLogs</code>); la conciliación remite a T05 sin que el nombre canónico de la colección de claves de idempotencia quede explícito en las fuentes leídas.</td><td>ADR-018</td></tr><tr><td>OBS-ADR-06</td><td>Aprobación del acceso de emergencia</td><td>RF-PLA-105 exige doble aprobación de plataforma (Soporte N2 + Seguridad); PA-IAM-06 admite emergencia &quot;por P-SUP con aviso inmediato y revisión posterior&quot;; RNF-NFR-237 pide &quot;aprobación de un segundo operador&quot; con vigencia ≤ 4 h. No queda claro si son el mismo circuito ni qué rol aprueba.</td><td>ADR-030</td></tr><tr><td>OBS-ADR-07</td><td>Datos reales en ensayos de migración</td><td>RN-NFR-014 prohíbe copiar datos reales a ambientes no productivos; PA-NFR-19 (asumida) admite copia real &quot;en un ambiente aislado de migración&quot; y RF-MIG-096 admite snapshots no anonimizados en &quot;el tenant de ensayo de la propia cooperativa&quot;. Ese ambiente no figura entre los siete de RF-PLA-109.</td><td>ADR-052, ADR-053</td></tr><tr><td>OBS-ADR-08</td><td>Credenciales de ProCoop</td><td>RF-INT-023 considera comprometidas las credenciales heredadas y exige regenerarlas en cada proveedor; RN-MIG-013 dice que &quot;se suprimen en la extracción y se reingresan en la bóveda&quot;, lo que admite reingresar el mismo valor.</td><td>ADR-032, ADR-053</td></tr><tr><td>OBS-ADR-09</td><td>Longitud mínima de contraseña</td><td>RF-IAM-040 fija mínimo 12 para staff y 10 para socios; RNF-NFR-061 fija mínimo 12 (8 con MFA obligatoria) sin distinguir socios.</td><td>ADR-026, ADR-027</td></tr><tr><td>OBS-ADR-10</td><td>Herramientas de prueba</td><td>La maestra §5.1 indica &quot;Vitest/Jest, Supertest&quot;; T08 RNF-NFR-141 indica <code>node --test</code> con c8 para el backend (ampliación de DT-07).</td><td>ADR-051</td></tr><tr><td>OBS-ADR-11</td><td>Alternativas de PA-COB-09</td><td>Las fuentes leídas no registran las opciones evaluadas para el identificador de pago en la migración (DEC-050).</td><td>ADR-055</td></tr></tbody></table><hr><h2 id="_5-referencias" tabindex="-1">5. Referencias <a class="header-anchor" href="#_5-referencias" aria-label="Permalink to &quot;5. Referencias&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Documento</th><th>Secciones usadas</th></tr></thead><tbody><tr><td><code>docs/especificacion/01-registro-decisiones.md</code></td><td>DEC-001 a DEC-089</td></tr><tr><td><code>docs/especificacion/00-ESPECIFICACION-MAESTRA.md</code></td><td>§3 decisiones rectoras; §5 arquitectura y stack (ARQ-01 a ARQ-08); §6 multitenancy; §7 permisos; §13 convenciones; §14 RNF</td></tr><tr><td><code>docs/especificacion/02-preguntas-abiertas.md</code> y anexos</td><td>Opciones de PA-PLA-01, PA-PLA-02, PA-PLA-05, PA-PLA-07, PA-PLA-08, PA-PLA-14, PA-IAM-01, PA-IAM-02, PA-IAM-06, PA-IAM-13, PA-INT-02, PA-INT-06, PA-INT-09, PA-NFR-03, PA-NFR-07, PA-NFR-14, PA-NFR-19, PA-BIA-01, PA-WFL-04, PA-WFL-05, PA-WFL-06, PA-CRM-06, PA-MIG-01, PA-MIG-04, PA-DAT-01, PA-DAT-02, PA-TEC-09, PA-CFG-P1-03, PA-CFG-P2-06, PA-CFG-P3-05, PA-COM-04, PA-FIS-03</td></tr><tr><td><code>anexos/T01-PLA-plataforma-saas.md</code></td><td>RF-PLA-001 a RF-PLA-165; RNF-PLA-001 a RNF-PLA-015; ARQ-PLA-01 a ARQ-PLA-12; §7.1, §7.6, §7.10</td></tr><tr><td><code>anexos/T02-IAM-identidad-roles-auditoria.md</code></td><td>RF-IAM-001 a RF-IAM-153; §7.17</td></tr><tr><td><code>anexos/T05-DAT-modelo-datos.md</code></td><td>RN-DAT-001 a RN-DAT-012; §7.1.1 a §7.1.15</td></tr><tr><td><code>anexos/T06-INT-integraciones.md</code></td><td>RF-INT-001 a RF-INT-086; RN-INT-005 a RN-INT-065; §7.3, §7.15</td></tr><tr><td><code>anexos/T07-MIG-migracion-procoop.md</code></td><td>RF-MIG-010, RF-MIG-011, RF-MIG-060, RF-MIG-062, RF-MIG-090, RF-MIG-095 a RF-MIG-097; RN-MIG-013</td></tr><tr><td><code>anexos/T08-NFR-no-funcionales-seguridad.md</code></td><td>RN-NFR-001 a RN-NFR-027; RNF-NFR-001 a RNF-NFR-259; RF-NFR-001 a RF-NFR-025; CTR-NFR-01 a CTR-NFR-23</td></tr><tr><td><code>docs/entregables-analisis-diseno/02-arquitectura-c4.md</code></td><td>§1.3, §2, §4, §6 a §11</td></tr><tr><td><code>docs/entregables-analisis-diseno/28-modelo-amenazas-seguridad.md</code></td><td>Modelo de amenazas que aplica los controles de estos ADR</td></tr></tbody></table>',371)])])}const g=a(n,[["render",r]]);export{m as __pageData,g as default};
